    fn finish_marked_cycle(vm: &mut Vm) {
        vm.finish_gc_marking().unwrap();
        vm.sweep_gc_some(usize::MAX);
        vm.finish_gc_cycle();
    }

    fn value_table(value: Value) -> TableId {
