                peak = peak.max(work.len());
            }
            assert!(peak <= 129, "wide table frontier grew to {peak}");
            assert!(children.iter().all(|&value| vm.marked_value(value)));
            finish_marked_cycle(&mut vm);
            assert!(
                children
