//! CourseContentsList display ownership, scroller fields and SetSong callbacks.
use super::*;
use sprites::{field, set};

pub(super) const METHODS: &[&str] = &[
    "Load",
    "SetFromGameState",
    "SetCurrentAndDestinationItem",
    "SetCurrentItem",
    "GetCurrentItem",
    "SetDestinationItem",
    "GetDestinationItem",
    "GetNumItems",
    "SetTransformFromFunction",
    "SetTransformFromHeight",
    "SetTransformFromWidth",
    "PositionItems",
    "GetSecondsToDestination",
    "SetSecondsPerItem",
    "SetLoop",
    "GetLoop",
    "SetPauseCountdownSeconds",
    "SetSecondsPauseBetweenItems",
    "GetSecondsPauseBetweenItems",
    "SetNumSubdivisions",
    "ScrollThroughAllItems",
    "ScrollWithPadding",
    "SetFastCatchup",
    "SetWrap",
    "SetMask",
    "SetNumItemsToDraw",
    "GetFullScrollLengthSeconds",
];

pub(super) fn install(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let methods = native_children::helper_function(call, b"course_methods")?;
    let methods = table(call, methods)?;
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    for &name in METHODS {
        let method = get(call, methods, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(invoke_bound, &captures, name)?;
        set(call, bound, name, function)?;
    }
    Ok(())
}

pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    for (key, value) in [
        ("current_item", 0.),
        ("destination_item", 0.),
        ("num_items", 1.),
    ] {
        put(call, actor, key, Value::Number(value))?;
    }
    let display = field(call, actor, "Display")?;
    if display == Value::Nil {
        return Ok(());
    }
    let display = table(call, display)?;
    let name = field(call, display, "Name")?;
    if name == Value::Nil {
        let name = call.try_intern(b"Display")?;
        set(call, display, "Name", name)?;
    } else {
        assets::text(call, name)?;
    }
    native_children::adopt(call, store, display, actor)?;
    if store.lock().unwrap().actors[&actor].offline_instance
        || get(call, display, b"Condition")? != Value::Boolean(false)
    {
        attach(call, store, scene, display)?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children
            .push(display);
        let len = call.raw_table_len(actor)?;
        let mut present = false;
        for i in 1..=len {
            present |= call.raw_table_get(actor, Value::Number(i as f64))? == Value::Table(display);
        }
        if !present {
            call.raw_table_set(
                actor,
                Value::Number((len + 1) as f64),
                Value::Table(display),
            )?;
        }
    }
    Ok(())
}

// The production constructor appends Display itself, including a plain Def
// table. Track it without adding instance methods or replacing its metatable.
pub(super) fn attach(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    {
        let guard = store.lock().unwrap();
        let actors = &guard.scenes[&scene].actors;
        if actors.contains(&actor) {
            return Ok(());
        }
    }
    if store.lock().unwrap().actors.contains_key(&actor) {
        store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&scene)
            .unwrap()
            .actors
            .push(actor);
        if !store.lock().unwrap().actors[&actor].initialized {
            let name = get(call, actor, b"Name")?;
            if matches!(name, Value::Number(_) | Value::String(_)) {
                let name = bytes(call, name)?;
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .load_name = Some(name);
            }
        }
        let mut descendants = children(call, store, actor)?;
        descendants.extend(
            store.lock().unwrap().actors[&actor]
                .wrappers
                .iter()
                .copied(),
        );
        for child in descendants {
            attach(call, store, scene, child)?;
        }
        return Ok(());
    }
    let name = get(call, actor, b"Name")?;
    let name = if matches!(name, Value::Number(_) | Value::String(_)) {
        Some(bytes(call, name)?)
    } else {
        None
    };
    let mut instance = Actor::new(scene, "Actor", None, name);
    instance.raw_instance = true;
    instance.initialized = boolean(call, actor, "__songlua_init_commands_ran")?;
    instance.started = boolean(call, actor, "__songlua_startup_commands_ran")?;
    if instance.initialized {
        let name = get(call, actor, b"__songlua_native_name")?;
        if matches!(name, Value::Number(_) | Value::String(_)) {
            instance.state.name = bytes(call, name)?;
        }
    }
    instance.registered = instance.initialized;
    let registry = table(call, call.captures()[0])?;
    call.raw_table_set(registry, Value::Table(actor), Value::Boolean(true))?;
    store.lock().unwrap().actors.insert(actor, instance);
    store
        .lock()
        .unwrap()
        .scenes
        .get_mut(&scene)
        .unwrap()
        .actors
        .push(actor);
    refresh_raw_children(call, store, actor, false)
}

pub(super) fn refresh_raw_children(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    compact: bool,
) -> Result<(), Error> {
    let selected = call.call(helper(call, 10)?, &[Value::Table(actor)])?[0];
    call.with_roots(&[selected], |call| {
        let selected = table(call, selected)?;
        let owners: Vec<_> = store
            .lock()
            .unwrap()
            .scenes
            .iter()
            .filter_map(|(id, scene)| scene.actors.contains(&actor).then_some(*id))
            .collect();
        let mut children = Vec::new();
        for i in 1..=call.raw_table_len(selected)? {
            let child = table(call, call.raw_table_get(selected, Value::Number(i as f64))?)?;
            for &scene in &owners {
                attach(call, store, scene, child)?;
            }
            children.push(child);
        }
        if compact {
            let entries = call.call(helper(call, 7)?, &[Value::Table(actor)])?[0];
            call.with_roots(&[entries], |call| {
                let entries = table(call, entries)?;
                for i in 1..=call.raw_table_len(entries)? {
                    let pair = table(call, call.raw_table_get(entries, Value::Number(i as f64))?)?;
                    let key = call.raw_table_get(pair, Value::Number(1.))?;
                    if matches!(key, Value::Number(n) if n >= 1. && n.fract()==0.) {
                        call.raw_table_set(actor, key, Value::Nil)?;
                    }
                }
                Ok(())
            })?;
            for (i, child) in children.iter().enumerate() {
                call.raw_table_set(actor, Value::Number((i + 1) as f64), Value::Table(*child))?;
            }
        }
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children = children;
        Ok(())
    })
}

pub(super) fn prepare_raw_init(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors[&actor].raw_instance {
        return Ok(());
    }
    let initialized = boolean(call, actor, "__songlua_init_commands_ran")?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .initialized = initialized;
    if initialized {
        return Ok(());
    }
    refresh_raw_children(call, store, actor, true)?;
    let name = get(call, actor, b"Name")?;
    let name = if matches!(name, Value::Number(_) | Value::String(_)) {
        Some(bytes(call, name)?)
    } else {
        None
    };
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .load_name = name;
    let empty = call.try_intern(b"")?;
    for name in [b"__songlua_native_name".as_slice(), b"__songlua_load_name"] {
        let key = call.try_intern(name)?;
        call.raw_table_set(actor, key, empty)?;
    }
    Ok(())
}

pub(super) fn share_child(
    call: &mut HostCall<'_>,
    store: &Shared,
    owner: TableId,
    child: TableId,
) -> Result<(), Error> {
    let owners: Vec<_> = store
        .lock()
        .unwrap()
        .scenes
        .iter()
        .filter_map(|(id, scene)| scene.actors.contains(&owner).then_some(*id))
        .collect();
    for scene in owners {
        attach(call, store, scene, child)?;
    }
    Ok(())
}

pub(super) fn publish_raw_name(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    original: Value,
) -> Result<(), Error> {
    let name = {
        let guard = store.lock().unwrap();
        let a = &guard.actors[&actor];
        (a.raw_instance || a.offline_instance).then(|| a.state.name.clone())
    };
    if let Some(name) = name {
        let value = if original == Value::Nil {
            call.try_intern(&name)?
        } else {
            original
        };
        let key = call.try_intern(b"__songlua_native_name")?;
        call.raw_table_set(actor, key, value)?;
        if original != Value::Nil {
            let key = call.try_intern(b"Name")?;
            call.raw_table_set(actor, key, original)?;
        }
        let key = call.try_intern(b"__songlua_load_name")?;
        call.raw_table_set(actor, key, Value::Nil)?;
    }
    Ok(())
}
pub(super) fn publish_raw_flag(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    key: &str,
) -> Result<(), Error> {
    let publish = {
        let guard = store.lock().unwrap();
        let a = &guard.actors[&actor];
        a.raw_instance || a.offline_instance
    };
    if publish {
        set(call, actor, key, Value::Boolean(true))?;
    }
    Ok(())
}
fn boolean(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<bool, Error> {
    // Lua's bool conversion uses truthiness; nil is the optional default.
    Ok(!matches!(
        field(call, actor, key)?,
        Value::Nil | Value::Boolean(false)
    ))
}
fn put(call: &mut HostCall<'_>, actor: TableId, key: &str, value: Value) -> Result<(), Error> {
    set(call, actor, &format!("__songlua_scroller_{key}"), value)
}
fn float(call: &mut HostCall<'_>, actor: TableId, key: &str, default: f32) -> Result<f32, Error> {
    let value = field(call, actor, &format!("__songlua_scroller_{key}"))?;
    if value == Value::Nil {
        Ok(default)
    } else {
        Ok(sprites::number(call, value)? as f32)
    }
}
fn count(call: &mut HostCall<'_>, actor: TableId) -> Result<i64, Error> {
    let value = field(call, actor, "__songlua_scroller_num_items")?;
    if value == Value::Nil {
        return Ok(1);
    }
    let n = sprites::number(call, value)?;
    if !(i64::MIN as f64..9223372036854775808.0).contains(&n) {
        return Err(call.error(b"scroller item count out of range"));
    }
    Ok(n as i64)
}
fn function(call: &HostCall<'_>, value: Value) -> Result<Option<Value>, Error> {
    match value {
        Value::Nil => Ok(None),
        Value::Function(_) | Value::Native(_) => Ok(Some(value)),
        _ => Err(call.error(b"function expected")),
    }
}
fn display(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<TableId>, Error> {
    let named = native_children::named_children(call, actor)?;
    call.with_roots(&[named], |call| {
        let value = field(call, table(call, named)?, "Display")?;
        if value == Value::Nil {
            Ok(None)
        } else {
            Ok(Some(table(call, value)?))
        }
    })
}
fn position(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let Some(display) = display(call, actor)? else {
        return Ok(());
    };
    call.with_roots(&[Value::Table(display)], |call| {
        let count = count(call, actor)?.max(1);
        let transform = field(call, actor, "__songlua_scroller_transform_function")?;
        if let Some(transform) = function(call, transform)? {
            call.call(
                transform,
                &[
                    Value::Table(display),
                    Value::Number(0.),
                    Value::Number(0.),
                    Value::Number(count as f64),
                ],
            )?;
        } else {
            for (key, axis) in [("item_height", "Y"), ("item_width", "X")] {
                let value = field(call, actor, &format!("__songlua_scroller_{key}"))?;
                if value != Value::Nil {
                    let offset = 0.0_f32 * sprites::number(call, value)? as f32;
                    set(call, display, axis, Value::Number(offset as f64))?;
                    break;
                }
            }
        }
        Ok(())
    })
}
fn call_method(
    call: &mut HostCall<'_>,
    object: TableId,
    name: &str,
    extra: Option<Value>,
) -> Result<Value, Error> {
    call.with_roots(
        &[Value::Table(object), extra.unwrap_or(Value::Nil)],
        |call| {
            let method = field(call, object, name)?;
            let Some(method) = function(call, method)? else {
                return Ok(Value::Nil);
            };
            let args = [Value::Table(object), extra.unwrap_or(Value::Nil)];
            Ok(call
                .call(method, &args[..if extra.is_some() { 2 } else { 1 }])?
                .first()
                .copied()
                .unwrap_or(Value::Nil))
        },
    )
}
fn gamestate(call: &mut HostCall<'_>, name: &str, extra: Option<Value>) -> Result<Value, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let value = field(call, globals, "GAMESTATE")?;
    if value == Value::Nil {
        Ok(Value::Nil)
    } else {
        call_method(call, table(call, value)?, name, extra)
    }
}
fn set_song(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    params: Value,
    leaf: bool,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        if !leaf && let Some((command, _)) = command(call, actor, b"SetSong")? {
            run_scoped(call, actor, command, Some(params))?;
        }
        if leaf {
            for child in native_children::group_members(call, actor)? {
                set_song(call, store, child, params, true)?;
            }
        }
    } else if leaf {
        leaves(call, store, actor, &mut |call, child| {
            run_named(call, store, child, b"SetSong", Some(params))
        })?;
    } else {
        run_named(call, store, actor, b"SetSong", Some(params))?;
    }
    Ok(())
}
fn populate(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let Some(display) = display(call, actor)? else {
        return Ok(());
    };
    call.with_roots(&[Value::Table(display)], |call| {
        for player in [b"PlayerNumber_P1", b"PlayerNumber_P2"] {
            let params = call.try_new_table()?;
            call.with_roots(&[Value::Table(params)], |call| {
                set(call, params, "Number", Value::Number(0.))?;
                let player = call.try_intern(player)?;
                set(call, params, "PlayerNumber", player)?;
                let song = gamestate(call, "GetCurrentSong", None)?;
                set(call, params, "Song", song)?;
                let steps = gamestate(call, "GetCurrentSteps", Some(player))?;
                set(call, params, "Steps", steps)?;
                for (name, method, default) in [
                    ("Meter", "GetMeter", "?"),
                    ("Difficulty", "GetDifficulty", "Difficulty_Medium"),
                ] {
                    let value = if let Value::Table(steps) = steps {
                        call_method(call, steps, method, None)?
                    } else {
                        Value::Nil
                    };
                    let value = if value == Value::Nil {
                        call.try_intern(default.as_bytes())?
                    } else {
                        value
                    };
                    set(call, params, name, value)?;
                }
                let params = Value::Table(params);
                set_song(call, store, display, params, false)?;
                set_song(call, store, display, params, true)
            })?;
        }
        Ok(())
    })
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    match name {
        "Load" => return sprites::method(call, store, actor, name),
        "SetFromGameState" => {
            if assets::field(call, actor, b"__songlua_actor_type")?
                .is_some_and(|s| s.eq_ignore_ascii_case("CourseContentsList"))
            {
                set(
                    call,
                    actor,
                    "__songlua_course_contents_from_gamestate",
                    Value::Boolean(true),
                )?;
                put(call, actor, "num_items", Value::Number(1.))?;
                populate(call, store, actor)?;
            }
        }
        "PositionItems" => position(call, actor)?,
        "GetCurrentItem" | "GetDestinationItem" | "GetSecondsPauseBetweenItems" => {
            let key = match name {
                "GetCurrentItem" => "current_item",
                "GetDestinationItem" => "destination_item",
                _ => "pause_between",
            };
            let value = float(call, actor, key, 0.)?;
            return call.push(Value::Number(value as f64));
        }
        "GetNumItems" => {
            let n = count(call, actor)?.max(0);
            return call.push(Value::Number(n as f64));
        }
        "GetLoop" => {
            let value = boolean(call, actor, "__songlua_scroller_loop")?;
            return call.push(Value::Boolean(value));
        }
        "GetSecondsToDestination" => {
            let current = float(call, actor, "current_item", 0.)?;
            let destination = float(call, actor, "destination_item", current)?;
            let seconds = float(call, actor, "seconds_per_item", 0.)?;
            return call.push(Value::Number(
                ((destination - current).abs() * seconds) as f64,
            ));
        }
        "GetFullScrollLengthSeconds" => {
            let count = count(call, actor)?.max(0) as f32;
            let seconds = float(call, actor, "seconds_per_item", 0.)?;
            let pause = float(call, actor, "pause_between", 0.)?;
            return call.push(Value::Number(
                (count - 1.).max(0.).mul_add(pause, count * seconds) as f64,
            ));
        }
        "SetTransformFromFunction" => {
            if matches!(value, Value::Function(_) | Value::Native(_)) {
                put(call, actor, "transform_function", value)?;
            }
        }
        "SetLoop" | "SetFastCatchup" | "SetWrap" | "SetMask" => {
            let key = match name {
                "SetLoop" => "loop",
                "SetFastCatchup" => "fast_catchup",
                "SetWrap" => "wrap",
                _ => "mask",
            };
            if name != "SetLoop" || call.arguments().len() > 1 {
                put(
                    call,
                    actor,
                    key,
                    Value::Boolean(!matches!(value, Value::Nil | Value::Boolean(false))),
                )?;
            }
        }
        "SetNumSubdivisions" | "SetNumItemsToDraw" => {
            if let Some(n) = integer_scalar(call, value) {
                put(
                    call,
                    actor,
                    if name == "SetNumSubdivisions" {
                        "num_subdivisions"
                    } else {
                        "num_items_to_draw"
                    },
                    Value::Number(n.max(0) as f64),
                )?;
            }
        }
        "ScrollThroughAllItems" | "ScrollWithPadding" => {
            let before = float_scalar(call, value, false).unwrap_or(0.).max(0.);
            let after = float_scalar(call, arg(call, 2), false)
                .unwrap_or(0.)
                .max(0.);
            let last = count(call, actor)?.saturating_sub(1).max(0) as f32;
            let destination = if name == "ScrollWithPadding" {
                put(call, actor, "current_item", Value::Number(-before as f64))?;
                last + after
            } else {
                last
            };
            put(
                call,
                actor,
                "destination_item",
                Value::Number(destination as f64),
            )?;
        }
        _ => {
            if let Some(value) = float_scalar(call, value, false) {
                let (key, clamp) = match name {
                    "SetCurrentAndDestinationItem" | "SetCurrentItem" => ("current_item", false),
                    "SetDestinationItem" => ("destination_item", true),
                    "SetTransformFromHeight" => ("item_height", false),
                    "SetTransformFromWidth" => ("item_width", false),
                    "SetSecondsPerItem" => ("seconds_per_item", true),
                    "SetPauseCountdownSeconds" => ("pause_countdown", true),
                    "SetSecondsPauseBetweenItems" => ("pause_between", true),
                    _ => unreachable!(),
                };
                let value = Value::Number(if clamp { value.max(0.) } else { value } as f64);
                put(call, actor, key, value)?;
                if name == "SetCurrentAndDestinationItem" {
                    put(call, actor, "destination_item", value)?;
                }
            }
        }
    }
    call.push(Value::Table(actor))
}

//! Existing offline Def constructors: in-place instances before Init.
use super::*;

const CLASSES: &[&str] = &[
    "Actor",
    "ActorFrame",
    "Sprite",
    "Banner",
    "ActorMultiVertex",
    "Sound",
    "BitmapText",
    "BPMDisplay",
    "RollingNumbers",
    "GraphDisplay",
    "SongMeterDisplay",
    "CourseContentsList",
    "DeviceList",
    "InputList",
    "Model",
    "Quad",
    "ActorProxy",
    "ActorFrameTexture",
];

pub(super) fn install(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let def = Value::Table(call.try_new_table()?);
    call.with_roots(&[def], |call| {
        let captures = call.captures().to_vec();
        for &class in CLASSES {
            let function = call.new_host_function_with_data(
                callback,
                &captures,
                Binding {
                    store: store.clone(),
                    op: Op::OfflineConstructor(class),
                },
            )?;
            let key = call.try_intern(class.as_bytes())?;
            call.raw_table_set(table(call, def)?, key, function)?;
        }
        let globals = table(call, helper(call, 5)?)?;
        sprites::set(call, globals, "Def", def)?;
        let loader = call.new_host_function_with_data(
            callback,
            &captures,
            Binding {
                store: store.clone(),
                op: Op::LoadPreparationActor,
            },
        )?;
        sprites::set(call, globals, "LoadActor", loader)?;
        let null = get(call, globals, b"NullActor")?;
        let null = table(call, null)?;
        sprites::set(call, null, "__songlua_def_owned", Value::Boolean(true))?;
        let mut guard = store.lock().unwrap();
        guard.offline_definitions = true;
        let null = guard.actors.get_mut(&null).expect("owned NullActor");
        null.offline_instance = true;
        null.capture.get_or_insert_with(capture::Capture::default);
        Ok(())
    })
}

pub(super) fn construct(
    call: &mut HostCall<'_>,
    store: &Shared,
    class: &'static str,
) -> Result<(), Error> {
    let supplied = match arg(call, 0) {
        Value::Table(actor) => Some(actor),
        _ => None,
    };
    let actor = create(call, store, class, supplied, false)?;
    call.push(Value::Table(actor))
}

pub(super) fn dummy(
    call: &mut HostCall<'_>,
    store: &Shared,
    class: &'static str,
) -> Result<TableId, Error> {
    create(call, store, class, None, true)
}

fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    class: &'static str,
    supplied: Option<TableId>,
    dummy: bool,
) -> Result<TableId, Error> {
    let actor = match supplied {
        Some(actor) => actor,
        None => call.try_new_table()?,
    };
    call.with_roots(&[Value::Table(actor)], |call| {
        let existing = store.lock().unwrap().actors.get(&actor).map(|a| {
            (
                a.scene,
                TemplateState::from(a),
                a.initialized,
                a.registered,
                a.parent,
            )
        });
        let scene = if let Some((scene, ..)) = &existing {
            *scene
        } else {
            new_scene(call, store)?
        };
        if existing.is_none() {
            store.lock().unwrap().constructor_scenes.insert(scene);
        }
        let kind = call.try_intern(class.as_bytes())?;
        call.call(
            helper(call, 1)?,
            &[
                kind,
                Value::Nil,
                Value::Table(actor),
                Value::Boolean(false),
                Value::Boolean(true),
            ],
        )?;
        let globals = table(call, helper(call, 5)?)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            let current = get(call, actor, key.as_bytes())?;
            let value = if key == "__songlua_script_dir" && current != Value::Nil {
                current
            } else {
                get(call, globals, key.as_bytes())?
            };
            if value != Value::Nil {
                sprites::set(call, actor, key, value)?;
            }
        }
        let name = get(call, actor, b"Name")?;
        let load_name = if matches!(name, Value::Number(_) | Value::String(_)) {
            Some(bytes(call, name)?)
        } else {
            None
        };
        let mut instance = Actor::new(scene, class, None, load_name);
        instance.offline_instance = true;
        instance.pending_init = true;
        instance.registered = dummy;
        instance.capture = store
            .lock()
            .unwrap()
            .constructing_capture
            .then(capture::Capture::default);
        if let Some((_, previous, initialized, registered, parent)) = existing {
            restore_pose(&mut instance, &previous);
            instance.state.name = previous.state.name;
            instance.initialized = initialized;
            instance.pending_init = !initialized;
            instance.registered = registered;
            instance.parent = parent;
        }
        let registry = table(call, call.captures()[0])?;
        call.raw_table_set(registry, Value::Table(actor), Value::Boolean(true))?;
        {
            let mut guard = store.lock().unwrap();
            let members = &mut guard.scenes.get_mut(&scene).unwrap().actors;
            if !members.contains(&actor) {
                members.push(actor);
            }
            guard
                .scenes
                .get_mut(&scene)
                .unwrap()
                .root
                .get_or_insert(actor);
            guard.actors.insert(actor, instance);
            if dummy {
                guard.actor_order.push(actor);
            }
        }
        if matches!(class, "Quad" | "ActorMultiVertex") {
            sprites::set(
                call,
                actor,
                "__songlua_default_texture",
                Value::Boolean(true),
            )?;
        }
        initialize_resources(
            call,
            store,
            scene,
            actor,
            class,
            if dummy {
                ResourceMode::Dummy
            } else {
                ResourceMode::Constructor
            },
        )?;
        call.call(helper(call, 13)?, &[Value::Table(actor)])?;
        own_children(call, store, actor)?;
        Ok(actor)
    })
}

fn restore_pose(actor: &mut Actor, previous: &TemplateState) {
    actor.current = previous.pose;
    actor.hibernate = previous.hibernate;
    actor.update_rate = previous.update_rate;
    actor.propagate = previous.propagate;
    actor.update_error_reported = previous.update_error_reported;
    actor.state.size = previous.state.size;
    actor.state.visible = previous.state.visible;
    actor.state.draw_order = previous.state.draw_order;
    actor.state.render = previous.state.render;
    actor.state.rotation = previous.state.rotation;
    actor.effects = previous.effects;
    actor.preparation_getters = previous.preparation_getters;
}

fn already_owned(call: &mut HostCall<'_>, actor: TableId) -> Result<bool, Error> {
    Ok(!matches!(
        get(call, actor, b"__songlua_def_owned")?,
        Value::Nil | Value::Boolean(false)
    ))
}

// Native cloning copies Lua state and rebinds methods; it does not rerun the
// resource constructor. Concatenation additionally leaves child identities shared.
pub(super) fn clone_actor(
    call: &mut HostCall<'_>,
    store: &Shared,
    source: TableId,
    own: bool,
) -> Result<TableId, Error> {
    let previous = TemplateState::from(&store.lock().unwrap().actors[&source]);
    let value = call.call(helper(call, 12)?, &[Value::Table(source)])?[0];
    call.with_roots(&[value], |call| {
        let actor = table(call, value)?;
        let scene = new_scene(call, store)?;
        let class = previous.state.class;
        let kind = call.try_intern(class.as_bytes())?;
        call.call(
            helper(call, 1)?,
            &[
                kind,
                Value::Nil,
                value,
                Value::Boolean(true),
                Value::Boolean(true),
            ],
        )?;
        let name = get(call, actor, b"Name")?;
        let name = if matches!(name, Value::String(_) | Value::Number(_)) {
            Some(bytes(call, name)?)
        } else {
            None
        };
        let mut instance = Actor::new(scene, class, None, name);
        restore_pose(&mut instance, &previous);
        instance.offline_instance = true;
        instance.pending_init = true;
        instance.registered = false;
        instance.capture = previous.capture;
        let registry = table(call, call.captures()[0])?;
        call.raw_table_set(registry, value, Value::Boolean(true))?;
        {
            let mut guard = store.lock().unwrap();
            guard.constructor_scenes.insert(scene);
            let owner = guard.scenes.get_mut(&scene).unwrap();
            owner.root = Some(actor);
            owner.actors.push(actor);
            guard.actors.insert(actor, instance);
        }
        initialize_resources(call, store, scene, actor, class, ResourceMode::OfflineClone)?;
        call.call(helper(call, 13)?, &[value])?;
        if own {
            own_children(call, store, actor)?;
        } else {
            share_children(call, store, actor)?;
        }
        Ok(actor)
    })
}

fn share_children(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let scene = store.lock().unwrap().actors[&actor].scene;
    let mut declared = Vec::new();
    for i in 1.. {
        match call.raw_table_get(actor, Value::Number(i as f64))? {
            Value::Nil => break,
            Value::Table(child) => {
                courses::attach(call, store, scene, child)?;
                declared.push(child);
            }
            _ => {}
        }
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .children = declared;
    for child in children(call, store, actor)? {
        courses::attach(call, store, scene, child)?;
    }
    Ok(())
}

// Transfer the implicit constructor owner after claiming its root. The native
// host keeps abandoned constructor objects until VM teardown; an explicitly
// owned scene instead supplies the existing release boundary for its subtree.
fn transfer(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    courses::attach(call, store, scene, actor)?;
    let old = {
        let guard = store.lock().unwrap();
        guard
            .constructor_scenes
            .iter()
            .copied()
            .filter(|id| *id != scene && guard.scenes[id].root == Some(actor))
            .collect::<Vec<_>>()
    };
    let mut guard = store.lock().unwrap();
    for id in old {
        guard.constructor_scenes.remove(&id);
        let previous = guard.scenes.remove(&id).unwrap();
        for member in previous.actors {
            if !guard.scenes[&scene].actors.contains(&member) {
                guard.scenes.get_mut(&scene).unwrap().actors.push(member);
            }
            if guard.actors[&member].scene == id {
                guard.actors.get_mut(&member).unwrap().scene = scene;
            }
        }
    }
    Ok(())
}

fn own_children(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let scene = store.lock().unwrap().actors[&actor].scene;
    let values = call
        .call(helper(call, 11)?, &[Value::Table(actor)])?
        .to_vec();
    call.with_roots(&values, |call| {
        let source = table(call, values[0])?;
        let entries = table(call, values[1])?;
        for i in 1..=call.raw_table_len(entries)? {
            let entry = table(call, call.raw_table_get(entries, Value::Number(i as f64))?)?;
            let key = call.raw_table_get(entry, Value::Number(1.))?;
            let child = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
            let typed = get(call, child, b"__songlua_actor_type")? != Value::Nil;
            let child = if typed && already_owned(call, child)? {
                clone_actor(call, store, child, true)?
            } else {
                child
            };
            if typed {
                sprites::set(call, child, "__songlua_def_owned", Value::Boolean(true))?;
                call.raw_table_set(source, key, Value::Table(child))?;
            }
            transfer(call, store, scene, child)?;
        }
        let mut children = Vec::new();
        for i in 1.. {
            match call.raw_table_get(actor, Value::Number(i as f64))? {
                Value::Nil => break,
                Value::Table(child) => {
                    transfer(call, store, scene, child)?;
                    children.push(child);
                }
                _ => {}
            }
        }
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children = children;
        // Native children (for example a supplied SongMeter Stream) also
        // leave their temporary constructor owner when this instance claims them.
        for child in super::children(call, store, actor)? {
            transfer(call, store, scene, child)?;
        }
        Ok(())
    })
}

pub(super) fn own_root(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    init: bool,
) -> Result<u64, Error> {
    let actor = if already_owned(call, actor)? {
        clone_actor(call, store, actor, true)?
    } else {
        actor
    };
    let existing = store.lock().unwrap().actors[&actor].scene;
    let scene = if store.lock().unwrap().scenes[&existing].root == Some(actor) {
        existing
    } else {
        let scene = new_scene(call, store)?;
        transfer(call, store, scene, actor)?;
        store.lock().unwrap().scenes.get_mut(&scene).unwrap().root = Some(actor);
        scene
    };
    store.lock().unwrap().constructor_scenes.remove(&scene);
    sprites::set(call, actor, "__songlua_def_owned", Value::Boolean(true))?;
    if init {
        super::prepare_init(store);
        if let Err(error) = initialize(call, store, actor) {
            release(call, store, scene)?;
            return Err(error);
        }
    }
    Ok(scene)
}

pub(super) fn prepare_init(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let initialized = !matches!(
        get(call, actor, b"__songlua_init_commands_ran")?,
        Value::Nil | Value::Boolean(false)
    );
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .initialized = initialized;
    if initialized {
        return Ok(());
    }
    courses::refresh_raw_children(call, store, actor, true)?;
    let name = get(call, actor, b"Name")?;
    let name = if matches!(name, Value::Number(_) | Value::String(_)) {
        Some(bytes(call, name)?)
    } else {
        None
    };
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .load_name = name;
    let empty = call.try_intern(b"")?;
    for key in ["__songlua_native_name", "__songlua_load_name"] {
        sprites::set(call, actor, key, empty)?;
    }
    Ok(())
}

//! Sound actors emit immediate host events; their RageSound handles retain
//! independent parameters and cached metadata through ordinary traced captures.
use super::*;
use crate::{SongLuaActorSound, SongLuaSoundEvent};
use std::sync::atomic::Ordering;

type LengthCache = Arc<Mutex<Option<(Option<String>, f32)>>>;
fn parameter(call: &HostCall<'_>) -> Value {
    arg(
        call,
        usize::from(matches!(call.arguments().first(), Some(Value::Table(_)))),
    )
}
#[derive(Clone)]
struct SoundBinding {
    store: Shared,
    name: &'static str,
    length: LengthCache,
}

pub(super) fn install(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let sound = call.try_new_table()?;
    let methods = call.try_new_table()?;
    let registry = table(call, call.captures()[0])?;
    // The actor's registry value traces the handle even if authored fields are
    // replaced. Its methods in turn retain the actor after scene retirement.
    call.raw_table_set(registry, Value::Table(actor), Value::Table(sound))?;
    let key = call.try_intern(b"__songlua_bound_methods")?;
    call.raw_table_set(actor, key, Value::Table(methods))?;
    for name in [b"__songlua_volume".as_slice(), b"__songlua_pitch"] {
        let key = call.try_intern(name)?;
        call.raw_table_set(sound, key, Value::Number(1.0))?;
    }
    let captures = [
        call.captures()[0],
        call.captures()[1],
        Value::Table(actor),
        Value::Table(sound),
    ];
    let length = Arc::new(Mutex::new(None));
    for (target, names) in [
        (methods, &["Load", "get", "stop", "playforplayer"][..]),
        (sound, &["pitch", "volume", "get_length", "SetProperty"][..]),
    ] {
        for &name in names {
            let function = call.new_host_function_with_data(
                bound,
                &captures,
                SoundBinding {
                    store: store.clone(),
                    name,
                    length: length.clone(),
                },
            )?;
            let key = call.try_intern(name.as_bytes())?;
            call.raw_table_set(target, key, function)?;
        }
    }
    store.lock().unwrap().actors.get_mut(&actor).unwrap().sound = Some(sound);
    Ok(())
}

fn path(
    call: &mut HostCall<'_>,
    actor: TableId,
    file: &str,
) -> Result<Option<std::path::PathBuf>, Error> {
    match assets::resolve(call, actor, file) {
        Err(error) if error.kind() == ErrorKind::Runtime => Ok(None),
        result => result,
    }
}

fn owner(call: &mut HostCall<'_>, actor: TableId) -> u64 {
    call.object_pointer(Value::Table(actor))
        .expect("captured actor") as u64
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let (is_sound, live) = {
        let store = store.lock().unwrap();
        (
            store.actors[&actor].state.class == "Sound",
            store.clock.live.load(Ordering::Relaxed),
        )
    };
    if !is_sound {
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .sprite_animate = name == "play";
        return call.push(Value::Table(actor));
    }
    match name {
        "play" | "playforplayer" => {
            if let Some(file) = assets::field(call, actor, b"File")?
                && let Some(path) = path(call, actor, &file)?
            {
                if live {
                    let owner = owner(call, actor);
                    store
                        .lock()
                        .unwrap()
                        .sounds
                        .push(SongLuaActorSound::Play { owner, path });
                } else {
                    let beat = match effects::values(call, false) {
                        Ok(values) => values[0],
                        Err(error) if error.kind() == ErrorKind::Runtime => 0.0,
                        Err(error) => return Err(error),
                    };
                    {
                        let mut store = store.lock().unwrap();
                        if let Some(queued_startup) = store.sound_capture {
                            let source_message = store.active_message.clone();
                            store.prepared_sounds.push(SongLuaSoundEvent {
                                beat,
                                path: path.clone(),
                                source_message,
                                queued_startup,
                            });
                        }
                    }
                    let key = call.try_intern(crate::SONG_LUA_SOUND_CALLS_KEY.as_bytes())?;
                    let calls = call.table_get(helper(call, 5)?, key)?;
                    if calls != Value::Nil {
                        let calls = table(call, calls)?;
                        let value = call.try_intern(path.to_string_lossy().as_bytes())?;
                        let index = Value::Number((call.raw_table_len(calls)? + 1) as f64);
                        call.raw_table_set(calls, index, value)?;
                    }
                }
            }
        }
        "pause" | "stop" if live => {
            let owner = owner(call, actor);
            let event = if name == "pause" {
                SongLuaActorSound::Pause {
                    owner,
                    paused: boolish(call, arg(call, 1)).unwrap_or(false),
                }
            } else {
                SongLuaActorSound::Stop { owner }
            };
            store.lock().unwrap().sounds.push(event);
        }
        _ => {}
    }
    call.push(Value::Table(actor))
}

fn bound(call: &mut HostCall<'_>) -> Result<(), Error> {
    let SoundBinding {
        store,
        name,
        length,
    } = call.function_data::<SoundBinding>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let sound = table(call, call.captures()[3])?;
    match name {
        "volume" | "pitch" => {
            let value = float_scalar(call, parameter(call), false)
                .ok_or_else(|| call.error(b"sound parameter must be a number"))?;
            let key = call.try_intern(if name == "volume" {
                b"__songlua_volume"
            } else {
                b"__songlua_pitch"
            })?;
            call.raw_table_set(sound, key, Value::Number(value as f64))?;
            call.push(Value::Table(sound))
        }
        "SetProperty" => call.push(Value::Boolean(false)),
        "get_length" => {
            // Read authored File before consulting the cache. Neither metadata
            // lookup nor decoder I/O holds a lock across reentrant Lua calls.
            let file = assets::field(call, actor, b"File")?;
            let cached = length
                .lock()
                .unwrap()
                .as_ref()
                .filter(|(previous, _)| previous == &file)
                .map(|(_, value)| *value);
            let value = if let Some(value) = cached {
                value
            } else {
                let path = match file.as_deref() {
                    Some(file) => path(call, actor, file)?,
                    None => None,
                };
                let value = path
                    .and_then(|path| {
                        deadlib_audio_decode::file_length_seconds(&path, Default::default()).ok()
                    })
                    .map(|seconds| (seconds * 1000.0).trunc() / 1000.0)
                    .unwrap_or(-1.0);
                *length.lock().unwrap() = Some((file, value));
                value
            };
            call.push(Value::Number(value as f64))
        }
        _ => {
            if !store.lock().unwrap().actors.contains_key(&actor) {
                return Err(call.error(b"sound actor has been released"));
            }
            match name {
                "get" => call.push(Value::Table(sound)),
                "Load" => {
                    let value = parameter(call);
                    if matches!(value, Value::String(_) | Value::Nil) {
                        if value != Value::Nil {
                            assets::text(call, value)?;
                        }
                        let key = call.try_intern(b"File")?;
                        call.table_set(Value::Table(actor), key, value)?;
                    }
                    call.push(Value::Table(actor))
                }
                _ => method(call, &store, actor, name),
            }
        }
    }
}

pub(super) fn retire(call: &mut HostCall<'_>, store: &Shared, actor: TableId) {
    let mut store = store.lock().unwrap();
    if store.actors[&actor].sound.is_some() && store.clock.live.load(Ordering::Relaxed) {
        store.sounds.push(SongLuaActorSound::Stop {
            owner: owner(call, actor),
        });
    }
}

//! ScreenGameplay's engine player constructor and life-meter bindings.
//! The player Init phase attaches its visible parts in this same scene.
use super::*;
use sprites::{field, set};

type Statistics = Arc<Mutex<super::super::statistics::State>>;

#[derive(Clone)]
pub(super) struct Build {
    store: Shared,
    statistics: Statistics,
    player: crate::SongLuaPlayerContext,
    index: usize,
    style: String,
    parts: bool,
}
#[derive(Clone)]
struct Method {
    store: Shared,
    statistics: Statistics,
    index: usize,
    name: &'static str,
}

impl Actors {
    // This is the Player constructor phase, before ScreenGameplay::Init attaches
    // its visible parts. Keep it private until the complete screen factory uses it.
    pub(in crate::rust_engine) fn player_base(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        index: usize,
        statistics: Statistics,
        catalog: Value,
    ) -> Result<ActorScene, Error> {
        self.player(vm, context, (index, false), statistics, catalog)
    }

    pub(in crate::rust_engine) fn gameplay_player(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        index: usize,
        statistics: Statistics,
        catalog: Value,
    ) -> Result<ActorScene, Error> {
        self.player(vm, context, (index, true), statistics, catalog)
    }

    fn player(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        (index, parts): (usize, bool),
        statistics: Statistics,
        catalog: Value,
    ) -> Result<ActorScene, Error> {
        let Some(player) = context.players.get(index) else {
            return vm.with_native_stack(|stack| {
                Err(stack.error(b"gameplay player index out of range"))
            });
        };
        let function = vm.new_host_function_with_data(
            construct,
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                catalog,
            ],
            Build {
                store: self.store.clone(),
                statistics,
                player: player.clone(),
                index,
                style: context.style_name.clone(),
                parts,
            },
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.registry,
            id: id as u64,
        })
    }
}

impl Build {
    pub(super) fn new(
        store: Shared,
        statistics: Statistics,
        context: &crate::SongLuaCompileContext,
        index: usize,
    ) -> Self {
        Self {
            store,
            statistics,
            player: context.players[index].clone(),
            index,
            style: context.style_name.clone(),
            parts: false,
        }
    }
    fn method(&self) -> Method {
        Method {
            store: self.store.clone(),
            statistics: self.statistics.clone(),
            index: self.index,
            name: "",
        }
    }
    pub(super) fn create_meter(&self, call: &mut HostCall<'_>, id: u64) -> Result<TableId, Error> {
        let store = self.store.clone();
        let method = self.method();
        let meter = dummy(
            call,
            &store,
            id,
            "LifeMeter",
            &format!("LifeP{}", method.index + 1),
            None,
        )?;
        set(
            call,
            meter,
            "__songlua_life",
            Value::Number(crate::SONG_LUA_INITIAL_LIFE as f64),
        )?;
        for name in ["GetLife", "IsFailing", "IsHot", "IsInDanger"] {
            bind(call, meter, &method, name)?;
        }
        // The native internal LifeMeter keeps its bound child queries even
        // though its public method class is Actor, not ActorFrame.
        top_screen::bind_queries(call, meter)?;
        Ok(meter)
    }
    pub(super) fn create_player(&self, call: &mut HostCall<'_>, id: u64) -> Result<TableId, Error> {
        let store = self.store.clone();
        let method = self.method();
        let player = &self.player;
        let style = &self.style;
        let actor = dummy(
            call,
            &store,
            id,
            "PlayerActor",
            &format!("PlayerP{}", method.index + 1),
            None,
        )?;
        set(
            call,
            actor,
            "__songlua_player_index",
            Value::Number(method.index as f64),
        )?;
        let style_value = call.try_intern(style.as_bytes())?;
        set(call, actor, "__songlua_style_name", style_value)?;
        set(call, actor, "__songlua_visible", Value::Boolean(true))?;
        for name in ["get_oitg_zoom_mode", "set_oitg_zoom_mode", "SetLife"] {
            bind(call, actor, &method, name)?;
        }
        let attack = dummy(call, &store, id, "ActorFrame", "", Some(actor))?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&attack)
            .unwrap()
            .current
            .x = -40.;
        call.raw_table_set(actor, Value::Number(1.), Value::Table(attack))?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children
            .push(attack);
        native_children::insert(call, actor, "", Value::Table(attack))?;
        set(
            call,
            actor,
            "__songlua_attack_display",
            Value::Table(attack),
        )?;
        {
            let mut guard = store.lock().unwrap();
            let pose = &mut guard.actors.get_mut(&actor).unwrap().current;
            pose.x = player.screen_x;
            pose.y = player.screen_y;
        }
        if let Some(path) = &player.judgment_texture {
            let path = crate::file_path_string(path);
            let path = call.try_intern(path.as_bytes())?;
            set(call, actor, "__songlua_judgment_texture", path)?;
        }
        Ok(actor)
    }
}

fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Build>().unwrap().clone();
    let store = data.store.clone();
    let style = data.style.clone();
    let parts = data.parts;
    let method = Method {
        store: store.clone(),
        statistics: data.statistics.clone(),
        index: data.index,
        name: "",
    };
    let id = {
        let mut guard = store.lock().unwrap();
        if guard.next >= (1u64 << 53) - 1 {
            return Err(call.error(b"actor scene identity exhausted"));
        }
        guard.next += 1;
        let id = guard.next;
        guard.scenes.insert(
            id,
            Scene {
                actors: Vec::new(),
                root: None,
                ended: false,
                sounds_retired: false,
            },
        );
        id
    };
    let result = (|| {
        let meter = data.create_meter(call, id)?;
        let actor = data.create_player(call, id)?;
        // ScreenGameplay owns the connection, after constructing the player.
        set(call, actor, "__songlua_life_meter", Value::Table(meter))?;
        if parts {
            player_parts::install(call, &store, id, actor, method.index, &style)?;
        }
        store.lock().unwrap().scenes.get_mut(&id).unwrap().root = Some(actor);
        Ok(())
    })();
    if let Err(error) = result {
        release(call, &store, id)?;
        return Err(error);
    }
    call.push(Value::Number(id as f64))
}

pub(super) fn dummy(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    kind: &str,
    name: &str,
    parent: Option<TableId>,
) -> Result<TableId, Error> {
    let attrs = call.try_new_table()?;
    call.with_roots(&[Value::Table(attrs)], |call| {
        let class = call.try_intern(kind.as_bytes())?;
        set(call, attrs, "Class", class)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            let value = field(call, table(call, helper(call, 5)?)?, key)?;
            if value != Value::Nil {
                assets::text(call, value)?;
                set(call, attrs, key, value)?;
            }
        }
        let node = call.call(helper(call, 2)?, &[Value::Table(attrs)])?[0];
        let actor = call.with_roots(&[node], |call| {
            Ok(build(call, store, scene, table(call, node)?, parent, false, true)?.unwrap())
        })?;
        let value = call.try_intern(name.as_bytes())?;
        set(call, actor, "Name", value)?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .native_children = true;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .name = name.as_bytes().to_vec();
        if let Some(parent) = parent {
            native_children::adopt(call, store, actor, parent)?;
        }
        Ok(actor)
    })
}

fn bind(
    call: &mut HostCall<'_>,
    actor: TableId,
    method: &Method,
    name: &'static str,
) -> Result<(), Error> {
    let mut data = method.clone();
    data.name = name;
    let captures = [
        call.captures()[0],
        call.captures()[1],
        call.captures()[2],
        // Life queries are bound to this meter. The player's setters and zoom
        // getter use their supplied receiver and must not retain an old player.
        if matches!(name, "GetLife" | "IsFailing" | "IsHot" | "IsInDanger") {
            Value::Table(actor)
        } else {
            Value::Nil
        },
    ];
    let function = call.new_host_function_with_data(invoke, &captures, data)?;
    call.with_roots(&[function], |call| {
        let bound = get(call, actor, b"__songlua_bound_methods")?;
        set(call, table(call, bound)?, name, function)
    })
}

fn raw_bool(call: &mut HostCall<'_>, actor: TableId, name: &[u8]) -> Result<bool, Error> {
    let key = call.try_intern(name)?;
    // The native typed bool conversion follows Lua truthiness; Option only
    // supplies the nil default. Strings and numbers are not conversion errors.
    Ok(!matches!(
        call.raw_table_get(actor, key)?,
        Value::Nil | Value::Boolean(false)
    ))
}
fn raw_set(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &[u8],
    value: Value,
) -> Result<(), Error> {
    let key = call.try_intern(name)?;
    call.raw_table_set(actor, key, value)
}

fn invoke(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Method>().unwrap().clone();
    let receiver = call.captures()[3];
    match data.name {
        "GetLife" | "IsFailing" | "IsHot" | "IsInDanger" => {
            let live = data
                .statistics
                .lock()
                .unwrap()
                .players
                .as_ref()
                .map(|p| p[data.index].life);
            let mut stack = call.native_stack()?;
            let value = if data.name == "GetLife"
                && let Some(life) = live
            {
                life
            } else {
                stack.push(receiver)?;
                stack.get_field(-1, b"__songlua_life")?;
                if stack.value(-1) == Some(Value::Nil) {
                    crate::SONG_LUA_INITIAL_LIFE
                } else {
                    stack.number(-1)? as f32
                }
            };
            stack.push(match data.name {
                "GetLife" => Value::Number(value as f64),
                "IsFailing" => Value::Boolean(value <= 0.),
                "IsHot" => Value::Boolean(value >= 1.),
                "IsInDanger" => Value::Boolean(value < crate::SONG_LUA_DANGER_LIFE),
                _ => unreachable!(),
            })?;
            stack.finish(1)
        }
        "get_oitg_zoom_mode" => {
            let actor = table(call, arg(call, 0))?;
            let value = raw_bool(call, actor, b"__songlua_oitg_zoom_mode")?;
            call.push(Value::Boolean(value))
        }
        "set_oitg_zoom_mode" => {
            let actor = table(call, arg(call, 0))?;
            let value = !matches!(arg(call, 1), Value::Nil | Value::Boolean(false));
            raw_set(
                call,
                actor,
                b"__songlua_oitg_zoom_mode",
                Value::Boolean(value),
            )?;
            call.push(Value::Table(actor))
        }
        "SetLife" => {
            let actor = table(call, arg(call, 0))?;
            let life = (call.number(1)? as f32).clamp(0., 1.);
            if raw_bool(call, actor, b"__songlua_inside_set_life")? {
                return Err(call.error(b"Do not call SetLife from inside LifeChangedMessageCommand because SetLife causes a LifeChangedMessageCommand."));
            }
            raw_set(
                call,
                actor,
                b"__songlua_inside_set_life",
                Value::Boolean(true),
            )?;
            let result = change_life(call, &data, actor, life);
            raw_set(
                call,
                actor,
                b"__songlua_inside_set_life",
                Value::Boolean(false),
            )?;
            result?;
            // Native typed i64 read, including string coercion and range checks.
            // This path adds no internal tonumber call visible to authored hooks.
            let globals = helper(call, 5)?;
            let mut stack = call.native_stack()?;
            stack.push(globals)?;
            let global_index = stack.top();
            stack.get_field(
                global_index as isize,
                crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
            )?;
            let count = if stack.value(-1) == Some(Value::Nil) {
                0
            } else {
                let value = stack.number(-1)?;
                if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
                    return Err(stack.error(b"side effect count is out of range"));
                }
                value as i64
            };
            stack.push_bytes(crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes())?;
            stack.push(Value::Number(count.saturating_add(1) as f64))?;
            stack.set_table(global_index as isize, false)?;
            stack.push(Value::Table(actor))?;
            stack.finish(1)
        }
        _ => unreachable!(),
    }
}

fn change_life(
    call: &mut HostCall<'_>,
    data: &Method,
    actor: TableId,
    life: f32,
) -> Result<(), Error> {
    {
        let mut state = data.statistics.lock().unwrap();
        if let Some(players) = state.players.as_mut() {
            players[data.index].life = life;
            players[data.index].life_record_latest = Some(life);
        }
    }
    let catalog = table(call, call.captures()[2])?;
    let key = call.try_intern(b"statistics_players")?;
    let players = table(call, call.raw_table_get(catalog, key)?)?;
    let stats = table(
        call,
        call.raw_table_get(players, Value::Number((data.index + 1) as f64))?,
    )?;
    raw_set(call, stats, b"__songlua_life", Value::Number(life as f64))?;
    if data
        .store
        .lock()
        .unwrap()
        .clock
        .live
        .load(std::sync::atomic::Ordering::Relaxed)
    {
        data.statistics
            .lock()
            .unwrap()
            .writes
            .push(crate::live::SongLuaLivePlayerWrite::SetLife {
                player: data.index,
                life,
            });
    }
    let key = call.try_intern(b"__songlua_life_meter")?;
    let meter = table(call, call.raw_table_get(actor, key)?)?;
    raw_set(call, meter, b"__songlua_life", Value::Number(life as f64))?;
    let params = call.try_new_table()?;
    call.with_roots(&[Value::Table(params)], |call| {
        let player = call.try_intern(format!("PlayerNumber_P{}", data.index + 1).as_bytes())?;
        raw_set(call, params, b"Player", player)?;
        raw_set(call, params, b"LifeMeter", Value::Table(meter))?;
        messages::dispatch(
            call,
            &data.store,
            b"LifeChanged",
            Some(Value::Table(params)),
            true,
        )
    })
}

//! Generated NoteField, Board and the eagerly owned style-column vector.
use super::*;
use generated_players::dummy;
use sprites::{field, set};

#[derive(Clone)]
struct Binding {
    store: Shared,
    scene: u64,
    name: &'static str,
}
struct Build {
    store: Shared,
    player: usize,
    style: String,
}
impl Actors {
    pub(in crate::rust_engine) fn note_field(
        &self,
        vm: &mut Vm,
        player: usize,
        style: &str,
    ) -> Result<ActorScene, Error> {
        let function = vm.new_host_function_with_data(
            construct,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Build {
                store: self.store.clone(),
                player,
                style: style.to_owned(),
            },
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.registry,
            id: id as u64,
        })
    }
}
fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let build = call.function_data::<Build>().unwrap();
    let store = build.store.clone();
    let player = build.player;
    let style = build.style.clone();
    let id = {
        let mut guard = store.lock().unwrap();
        if guard.next >= (1u64 << 53) - 1 {
            return Err(call.error(b"actor scene identity exhausted"));
        }
        guard.next += 1;
        let id = guard.next;
        guard.scenes.insert(
            id,
            Scene {
                actors: Vec::new(),
                root: None,
                ended: false,
                sounds_retired: false,
            },
        );
        id
    };
    let result = create(call, &store, id, player, &style);
    match result {
        Ok(actor) => store.lock().unwrap().scenes.get_mut(&id).unwrap().root = Some(actor),
        Err(error) => {
            release(call, &store, id)?;
            return Err(error);
        }
    }
    call.push(Value::Number(id as f64))
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    player: usize,
    style: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "NoteField", "", None)?;
    let board = dummy(call, store, scene, "Sprite", "Board", Some(actor))?;
    let path =
        crate::blank_texture::load_native_blank_texture().map_err(|e| call.error(e.as_bytes()))?;
    let path = call.try_intern(path.as_bytes())?;
    sprites::set_texture(call, store, board, path, false)?;
    call.raw_table_set(actor, Value::Number(1.), Value::Table(board))?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .children
        .push(board);
    native_children::insert(call, actor, "Board", Value::Table(board))?;
    set(
        call,
        actor,
        "__songlua_player_index",
        Value::Number(player as f64),
    )?;
    let style = call.try_intern(style.as_bytes())?;
    set(call, actor, "__songlua_style_name", style)?;
    let kind = call.try_intern(b"NoteField")?;
    set(call, actor, "__songlua_player_child_name", kind)?;
    set(call, actor, "__songlua_beat_bars", Value::Boolean(false))?;
    let alpha = call.try_new_table()?;
    set(
        call,
        actor,
        "__songlua_beat_bars_alpha",
        Value::Table(alpha),
    )?;
    for name in [
        "GetColumnActors",
        "get_column_actors",
        "SetBeatBars",
        "SetBeatBarsAlpha",
        "SetDidTapNoteCallback",
        "did_tap_note",
    ] {
        let function = call.new_host_function_with_data(
            method,
            &[call.captures()[0], call.captures()[1], Value::Table(actor)],
            Binding {
                store: store.clone(),
                scene,
                name,
            },
        )?;
        call.with_roots(&[function], |call| {
            let value = get(call, actor, b"__songlua_bound_methods")?;
            let bound = table(call, value)?;
            set(call, bound, name, function)?;
            if name == "SetDidTapNoteCallback" {
                set(call, bound, "set_did_tap_note_callback", function)?;
            }
            Ok(())
        })?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .current
        .y = f32::midpoint(crate::THEME_RECEPTOR_Y_STD, crate::THEME_RECEPTOR_Y_REV);
    columns(call, store, scene, actor)?;
    Ok(actor)
}

fn text(call: &HostCall<'_>, value: Value) -> Result<String, Error> {
    let Value::String(id) = value else {
        return Err(call.error(b"string field expected"));
    };
    std::str::from_utf8(
        call.string_bytes(id)
            .ok_or_else(|| call.error(b"string is not retained"))?,
    )
    .map(str::to_owned)
    .map_err(|_| call.error(b"UTF-8 string expected"))
}
fn tolerate<T>(result: Result<T, Error>) -> Result<Option<T>, Error> {
    match result {
        Ok(value) => Ok(Some(value)),
        Err(error) if error.kind() == ErrorKind::Runtime => Ok(None),
        Err(error) => Err(error),
    }
}
fn current_style(call: &mut HostCall<'_>) -> Result<String, Error> {
    let globals = helper(call, 5)?;
    let selected = tolerate((|| {
        let key = call.try_intern(b"GAMESTATE")?;
        let state = call.table_get(globals, key)?;
        call.with_roots(&[state], |call| {
            let key = call.try_intern(b"__songlua_current_style")?;
            let slots = table(call, call.raw_table_get(table(call, state)?, key)?)?;
            call.raw_table_get(slots, Value::Number(1.))
        })
    })())?;
    let selected = if let Some(selected) = selected {
        Some(selected)
    } else {
        tolerate((|| {
            let key = call.try_intern(b"GAMESTATE")?;
            let state = call.table_get(globals, key)?;
            call.with_roots(&[state], |call| {
                let function = field(call, table(call, state)?, "GetCurrentStyle")?;
                if !matches!(function, Value::Function(_) | Value::Native(_)) {
                    return Err(call.error(b"style getter expected"));
                }
                Ok(call
                    .call(function, &[state])?
                    .first()
                    .copied()
                    .unwrap_or(Value::Nil))
            })
        })())?
    };
    let Some(Value::Table(style)) = selected else {
        return Ok("single".into());
    };
    call.with_roots(&[Value::Table(style)], |call| {
        let key = call.try_intern(b"__songlua_style_key")?;
        if let Some(key) = tolerate(text(call, call.raw_table_get(style, key)?))? {
            return Ok(key);
        }
        let value = tolerate((|| {
            let function = field(call, style, "GetName")?;
            if !matches!(function, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"style getter expected"));
            }
            let value = call
                .call(function, &[Value::Table(style)])?
                .first()
                .copied()
                .unwrap_or(Value::Nil);
            text(call, value)
        })())?;
        Ok(value.unwrap_or_else(|| "single".into()))
    })
}

fn columns(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<Value, Error> {
    let cached = field(call, actor, "__songlua_note_columns")?;
    if cached != Value::Nil {
        table(call, cached)?;
        return Ok(cached);
    }
    if !store.lock().unwrap().scenes.contains_key(&scene) {
        return Err(call.error(b"NoteField scene has been released"));
    }
    let columns = call.try_new_table()?;
    call.with_roots(&[Value::Table(columns)], |call| {
        let value = field(call, actor, "__songlua_player_index")?;
        let player = if value == Value::Nil {
            0
        } else {
            let n = sprites::number(call, value)?;
            if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&n) {
                return Err(call.error(b"player index out of range"));
            }
            n as i64 as usize
        };
        let value = field(call, actor, "__songlua_style_name")?;
        let style = if value == Value::Nil {
            current_style(call)?
        } else {
            text(call, value)?
        };
        for index in 0..crate::song_lua_style_info(&style).columns {
            let column = dummy(call, store, scene, "NoteColumnRenderer", "", Some(actor))?;
            set(
                call,
                column,
                "__songlua_player_index",
                Value::Number(player as i64 as f64),
            )?;
            set(
                call,
                column,
                "__songlua_column_index",
                Value::Number(index as f64),
            )?;
            let x = crate::song_lua_style_column_x(&style, index);
            if !store
                .lock()
                .unwrap()
                .clock
                .live
                .load(std::sync::atomic::Ordering::Relaxed)
            {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&column)
                    .unwrap()
                    .current
                    .x = x;
            }
            for (key, value) in [
                ("__songlua_state_x", x),
                ("__songlua_state_y", 0.),
                ("__songlua_state_z", 0.),
            ] {
                set(call, column, key, Value::Number(value as f64))?;
            }
            for (field_name, name, alias) in [
                ("__songlua_pos_handler", "GetPosHandler", "get_pos_handler"),
                ("__songlua_rot_handler", "GetRotHandler", "get_rot_handler"),
                (
                    "__songlua_zoom_handler",
                    "GetZoomHandler",
                    "get_zoom_handler",
                ),
            ] {
                let handler = splines::handler(call)?;
                set(call, column, field_name, Value::Table(handler))?;
                let getter = call.new_host_function(
                    |call| call.push(call.captures()[0]),
                    &[Value::Table(handler)],
                )?;
                let value = get(call, column, b"__songlua_bound_methods")?;
                let bound = table(call, value)?;
                set(call, bound, name, getter)?;
                set(call, bound, alias, getter)?;
            }
            call.raw_table_set(
                columns,
                Value::Number((index + 1) as f64),
                Value::Table(column),
            )?;
        }
        set(call, actor, "__songlua_note_columns", Value::Table(columns))?;
        lifecycle::invalidate_plans(call, store)?;
        Ok(Value::Table(columns))
    })
}

fn method(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let offset = usize::from(matches!(arg(call, 0), Value::Table(_)));
    match data.name {
        "GetColumnActors" => {
            let child = field(call, actor, "__songlua_player_child_name")?;
            let mut valid =
                child != Value::Nil && text(call, child)?.eq_ignore_ascii_case("NoteField");
            if !valid {
                let kind = field(call, actor, "__songlua_actor_type")?;
                valid = kind != Value::Nil && text(call, kind)?.eq_ignore_ascii_case("NoteField");
            }
            let value = if valid {
                columns(call, &data.store, data.scene, actor)?
            } else {
                Value::Nil
            };
            return call.push(value);
        }
        "get_column_actors" => {
            let function = field(call, actor, "GetColumnActors")?;
            let value = if matches!(function, Value::Function(_) | Value::Native(_)) {
                call.call(function, &[Value::Table(actor)])?
                    .first()
                    .copied()
                    .unwrap_or(Value::Nil)
            } else {
                Value::Nil
            };
            return call.push(value);
        }
        "SetBeatBars" => {
            if let Some(value) = call.arguments().get(offset).copied() {
                set(
                    call,
                    actor,
                    "__songlua_beat_bars",
                    Value::Boolean(!matches!(value, Value::Nil | Value::Boolean(false))),
                )?;
                return finish_effect(call, actor);
            }
        }
        "SetBeatBarsAlpha" => {
            let alpha = call.try_new_table()?;
            call.with_roots(&[Value::Table(alpha)], |call| {
                for index in 0..4 {
                    let value =
                        splines::optional_float(call, arg(call, offset + index)).unwrap_or(0.);
                    call.raw_table_set(
                        alpha,
                        Value::Number((index + 1) as f64),
                        Value::Number(value as f64),
                    )?;
                }
                set(
                    call,
                    actor,
                    "__songlua_beat_bars_alpha",
                    Value::Table(alpha),
                )
            })?;
            return finish_effect(call, actor);
        }
        "SetDidTapNoteCallback" => {
            let value = arg(call, 1);
            let value = if matches!(value, Value::Function(_) | Value::Native(_)) {
                value
            } else {
                Value::Nil
            };
            set(call, actor, "__songlua_did_tap_note_callback", value)?;
        }
        "did_tap_note" => {
            let column = match arg(call, offset) {
                Value::Number(n) if n.is_finite() => {
                    n.round().clamp(i32::MIN as f64, i32::MAX as f64) as i32
                }
                Value::String(id) => call
                    .string_bytes(id)
                    .and_then(|s| std::str::from_utf8(s).ok())
                    .and_then(|s| {
                        s.trim()
                            .parse::<i32>()
                            .ok()
                            .or_else(|| s.trim().parse::<f32>().ok().map(|n| n.round() as i32))
                    })
                    .unwrap_or(0),
                _ => 0,
            };
            let score = arg(call, offset + 1);
            let bright = !matches!(arg(call, offset + 2), Value::Nil | Value::Boolean(false));
            set(
                call,
                actor,
                "__songlua_last_tap_note_column",
                Value::Number(column as f64),
            )?;
            set(call, actor, "__songlua_last_tap_note_score", score)?;
            set(
                call,
                actor,
                "__songlua_last_tap_note_bright",
                Value::Boolean(bright),
            )?;
            let callback = field(call, actor, "__songlua_did_tap_note_callback")?;
            if callback != Value::Nil {
                if !matches!(callback, Value::Function(_) | Value::Native(_)) {
                    return Err(call.error(b"tap callback must be a function"));
                }
                call.call(
                    callback,
                    &[Value::Number(column as f64), score, Value::Boolean(bright)],
                )?;
            }
            return finish_effect(call, actor);
        }
        _ => unreachable!(),
    }
    call.push(Value::Table(actor))
}

fn finish_effect(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let globals = helper(call, 5)?;
    let mut stack = call.native_stack()?;
    stack.push(globals)?;
    let target = stack.top();
    stack.get_field(
        target as isize,
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
    )?;
    let count = if stack.value(-1) == Some(Value::Nil) {
        0
    } else {
        let value = stack.number(-1)?;
        if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
            return Err(stack.error(b"side effect count is out of range"));
        }
        value as i64
    };
    stack.push_bytes(crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes())?;
    stack.push(Value::Number(count.saturating_add(1) as f64))?;
    stack.set_table(target as isize, false)?;
    stack.push(Value::Table(actor))?;
    stack.finish(1)
}

pub(super) fn update_columns(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Vec<TableId>, Error> {
    let key = call.try_intern(b"__songlua_note_columns")?;
    let columns = call.raw_table_get(actor, key)?;
    if columns == Value::Nil {
        return Ok(Vec::new());
    }
    let columns = table(call, columns)?;
    let mut result = Vec::new();
    for index in 1usize.. {
        let value = call.raw_table_get(columns, Value::Number(index as f64))?;
        if value == Value::Nil {
            break;
        }
        result.push(table(call, value)?);
    }
    Ok(result)
}

//! ScreenGameplay's owned base tree, before the remaining theme files load.
use super::super::managers::screen::Requests;
use super::*;
use generated_players::dummy;
use sprites::set;

#[derive(Clone)]
struct Build {
    store: Shared,
    context: crate::SongLuaCompileContext,
    statistics: Arc<Mutex<super::super::statistics::State>>,
}

impl Actors {
    pub(in crate::rust_engine) fn gameplay_screen(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        statistics: Arc<Mutex<super::super::statistics::State>>,
        catalog: Value,
        requests: Arc<Mutex<Requests>>,
    ) -> Result<(ActorScene, [Value; crate::LUA_PLAYERS]), Error> {
        underlay::ensure_helpers(vm, self.helpers)?;
        screen_parts::ensure_helpers(vm, self.helpers)?;
        let function = vm.new_host_function_with_data(
            construct,
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                catalog,
            ],
            Build {
                store: self.store.clone(),
                context: context.clone(),
                statistics,
            },
        )?;
        let values = vm.call(function, &[])?.to_vec();
        let Value::Number(id) = values[0] else {
            unreachable!()
        };
        let scene = ActorScene {
            owner: self.registry,
            id: id as u64,
        };
        let children = [values[1], values[2], values[3], values[4], values[5]];
        if let Err(error) = self.bind_top_screen(
            vm,
            catalog,
            children,
            context.players.each_ref().map(|p| p.enabled),
            requests,
        ) {
            self.release(vm, scene)?;
            return Err(error);
        }
        Ok((scene, [values[2], values[3]]))
    }
}

fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Build>().unwrap().clone();
    let scene = new_scene(call, &data.store)?;
    let previous = {
        let mut store = data.store.lock().unwrap();
        let capture = !store.clock.live.load(std::sync::atomic::Ordering::Relaxed);
        std::mem::replace(&mut store.constructing_capture, capture)
    };
    let result = assemble(call, &data, scene);
    data.store.lock().unwrap().constructing_capture = previous;
    let actors = match result {
        Ok(actors) => actors,
        Err(error) => {
            release(call, &data.store, scene)?;
            return Err(error);
        }
    };
    call.push(Value::Number(scene as f64))?;
    for actor in actors {
        call.push(Value::Table(actor))?;
    }
    Ok(())
}

fn assemble(call: &mut HostCall<'_>, data: &Build, scene: u64) -> Result<[TableId; 5], Error> {
    let store = &data.store;
    let context = &data.context;
    let top = top_screen::create(call, store, scene, context)?;
    store.lock().unwrap().scenes.get_mut(&scene).unwrap().root = Some(top);
    let builds = [0, 1].map(|index| {
        generated_players::Build::new(store.clone(), data.statistics.clone(), context, index)
    });
    // The native screen constructs both meters, then both players, even when
    // only one player is enabled. Parts are attached after screen parenting.
    let meters = [
        builds[0].create_meter(call, scene)?,
        builds[1].create_meter(call, scene)?,
    ];
    let players = [
        builds[0].create_player(call, scene)?,
        builds[1].create_player(call, scene)?,
    ];
    for (index, &player) in players.iter().enumerate() {
        native_children::adopt(call, store, player, top)?;
        set(
            call,
            player,
            "__songlua_life_meter",
            Value::Table(meters[index]),
        )?;
        player_parts::install(call, store, scene, player, index, &context.style_name)?;
    }
    for (index, &meter) in meters.iter().enumerate() {
        native_children::adopt(call, store, meter, top)?;
        set(
            call,
            meter,
            "__songlua_theme_hibernating",
            Value::Boolean(true),
        )?;
        tag(call, meter, crate::top_screen_life_meter_name(index))?;
    }
    for (index, &player) in players.iter().enumerate() {
        if context.players[index].enabled {
            native_children::insert(
                call,
                top,
                crate::top_screen_player_name(index),
                Value::Table(player),
            )?;
        }
    }
    for (index, &meter) in meters.iter().enumerate() {
        if context.players[index].enabled {
            native_children::insert(
                call,
                top,
                crate::top_screen_life_meter_name(index),
                Value::Table(meter),
            )?;
        }
    }
    for &name in crate::TOP_SCREEN_THEME_CHILD_NAMES {
        let player = crate::top_screen_score_index(name)
            .or_else(|| crate::top_screen_steps_display_index(name))
            .or_else(|| {
                ["StepsDescription", "PlayerOptions", "OniGameOver"]
                    .iter()
                    .find_map(|prefix| {
                        name.strip_prefix(prefix).and_then(|side| match side {
                            "P1" => Some(0),
                            "P2" => Some(1),
                            _ => None,
                        })
                    })
            });
        if player.is_some_and(|index| !context.players[index].enabled) {
            continue;
        }
        let child = if name == "Underlay" {
            underlay::create(call, store, scene, top)?
        } else {
            screen_parts::create(call, store, scene, name)?
        };
        underlay::set_name(call, store, child, name)?;
        underlay::copy_tags(call, top, child)?;
        native_children::adopt(call, store, child, top)?;
        tag(call, child, name)?;
        if crate::top_screen_score_index(name).is_some()
            || crate::top_screen_steps_display_index(name).is_some()
            || name.starts_with("StepsDescription")
            || matches!(name, "Header" | "Footer")
        {
            set(
                call,
                child,
                "__songlua_theme_hibernating",
                Value::Boolean(true),
            )?;
        }
        if let Some(index) = crate::top_screen_steps_display_index(name) {
            let value = call.try_intern(context.players[index].difficulty.sm_name().as_bytes())?;
            set(call, child, "__songlua_preferred_difficulty", value)?;
        }
        native_children::insert(call, top, name, Value::Table(child))?;
    }
    let registry = native_children::helper_function(call, b"native_registry")?;
    let registry = call.call(registry, &[Value::Table(top)])?[0];
    let mut ordered = call.with_roots(&[registry], |call| {
        let registry = table(call, registry)?;
        let mut ordered = Vec::new();
        for name in [
            "SongBackground",
            "Underlay",
            "PlayerP1",
            "PlayerP2",
            "LifeP1",
            "LifeP2",
            "ScoreP1",
            "ScoreP2",
            "StepsDisplayP1",
            "StepsDisplayP2",
            "Overlay",
            "SongForeground",
            "In",
            "Debug",
        ]
        .into_iter()
        .chain(crate::TOP_SCREEN_THEME_CHILD_NAMES.iter().copied())
        {
            let value = get(call, registry, name.as_bytes())?;
            if value != Value::Nil {
                let child = table(call, value)?;
                if !ordered.contains(&child) {
                    ordered.push(child);
                }
            }
        }
        Ok(ordered)
    })?;
    write_order(call, store, top, &ordered)?;
    // These native messages reach the already-constructed theme. They bypass
    // authored broadcast recording and never enter a song's startup output.
    for (index, &meter) in meters.iter().enumerate() {
        if !context.players[index].enabled {
            continue;
        }
        let params = call.try_new_table()?;
        call.with_roots(&[Value::Table(params)], |call| {
            let player = call.try_intern(crate::player_number_name(index).as_bytes())?;
            set(call, params, "Player", player)?;
            set(call, params, "LifeMeter", Value::Table(meter))?;
            messages::dispatch(
                call,
                store,
                b"LifeChanged",
                Some(Value::Table(params)),
                false,
            )
        })?;
    }
    let mut unnamed = Vec::new();
    for role in ["Toasty", "NextSong", "Ready", "Go", "Failed"] {
        let actor = dummy(call, store, scene, "ActorFrame", "", Some(top))?;
        set(call, actor, "__songlua_transition_state", Value::Number(0.))?;
        let value = call.try_intern(role.as_bytes())?;
        set(call, actor, "__songlua_screen_actor_role", value)?;
        if role == "Toasty" {
            screen_parts::invoke(call, actor, "visible", &[Value::Boolean(false)])?;
        }
        unnamed.push(actor);
        ordered.push(actor);
    }
    let unnamed = underlay::group(call, &unnamed)?;
    native_children::insert(call, top, "", unnamed)?;
    set(
        call,
        top,
        "__songlua_owned_child_lookup",
        Value::Boolean(true),
    )?;
    // Stable sorting first restores native construction order and then draw
    // order. In particular all players precede their OniGameOver displays.
    let construction = [
        "Underlay",
        "Overlay",
        "Header",
        "Footer",
        "In",
        "Out",
        "Cancel",
        "SongBackground",
        "SongForeground",
        "Toasty",
        "PlayerP1",
        "PlayerP2",
        "OniGameOverP1",
        "OniGameOverP2",
        "NextSong",
        "LifeP1",
        "LifeP2",
        "ScoreP1",
        "ScoreP2",
        "StepsDescriptionP1",
        "PlayerOptionsP1",
        "StepsDisplayP1",
        "StepsDescriptionP2",
        "PlayerOptionsP2",
        "StepsDisplayP2",
        "SongOptions",
        "ActiveAttackListP1",
        "ActiveAttackListP2",
        "LyricDisplay",
        "Ready",
        "Go",
        "Failed",
        "Debug",
    ];
    let mut keys = Vec::new();
    for &actor in &ordered {
        let name = actor_name(call, store, actor)?;
        let name =
            String::from_utf8(name).map_err(|error| call.error(error.to_string().as_bytes()))?;
        let role = get(call, actor, b"__songlua_screen_actor_role")?;
        let role = if role == Value::Nil {
            None
        } else {
            Some(assets::text(call, role)?)
        };
        let rank = construction
            .iter()
            .position(|known| *known == role.as_deref().unwrap_or(&name))
            .unwrap_or(construction.len());
        let order = match name.as_str() {
            "SongBackground" => -200,
            "Underlay" => -100,
            "Overlay" => 100,
            "SongForeground" => 101,
            "Debug" => 199,
            "In" | "Out" | "Cancel" => 200,
            _ if matches!(role.as_deref(), Some("NextSong" | "Failed")) => 199,
            _ => 0,
        };
        let key = call.try_intern(b"__songlua_state_draw_order")?;
        call.raw_table_set(actor, key, Value::Number(order as f64))?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .draw_order = order;
        keys.push((actor, rank, order));
    }
    keys.sort_by_key(|&(_, rank, _)| rank);
    keys.sort_by_key(|&(_, _, order)| order);
    ordered = keys.into_iter().map(|(actor, _, _)| actor).collect();
    write_order(call, store, top, &ordered)?;
    lifecycle::invalidate_plans(call, store)?;
    Ok([top, players[0], players[1], meters[0], meters[1]])
}

fn tag(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<(), Error> {
    let value = call.try_intern(name.as_bytes())?;
    set(call, actor, "__songlua_top_screen_child_name", value)
}

fn write_order(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    ordered: &[TableId],
) -> Result<(), Error> {
    for (index, &child) in ordered.iter().enumerate() {
        call.raw_table_set(
            actor,
            Value::Number((index + 1) as f64),
            Value::Table(child),
        )?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .children = ordered.to_vec();
    Ok(())
}

//! Generated ScreenGameplay display children, before screen ownership/On commands.
use super::*;
use generated_players::dummy;
use sprites::{field, set};

struct Build {
    store: Shared,
    name: String,
}

const LYRIC_COMMANDS: &[u8] = br#"return function()
return {
    Back = function(self) self:LyricCommand('Back') end,
    Front = function(self) self:LyricCommand('Front') end,
    SetNoReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y + 160) end,
    SetReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y - 140) end,
    SetOneReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y - 205) end,
}
end"#;
const LYRIC_INITIAL: &[u8] = br#"return function()
local allReverse, anyReverse = true, false
for _, player in ipairs(GAMESTATE:GetEnabledPlayers()) do
    local reverse = GAMESTATE:GetPlayerState(player):GetPlayerOptions('ModsLevel_Current'):Reverse() == 1
    allReverse = allReverse and reverse
    anyReverse = anyReverse or reverse
end
return allReverse and 'SetReverse' or anyReverse and 'SetOneReverse' or 'SetNoReverse'
end"#;

impl Actors {
    pub(in crate::rust_engine) fn screen_part(
        &self,
        vm: &mut Vm,
        name: &str,
    ) -> Result<ActorScene, Error> {
        ensure_helpers(vm, self.helpers)?;
        let function = vm.new_host_function_with_data(
            construct,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Build {
                store: self.store.clone(),
                name: name.to_owned(),
            },
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.registry,
            id: id as u64,
        })
    }
}

pub(super) fn ensure_helpers(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    steps_displays::ensure_helpers(vm, helpers)?;
    transitions::ensure_helpers(vm, helpers)?;
    for (key, source, name) in [
        (
            "lyric_commands",
            LYRIC_COMMANDS,
            b"@theme:/metrics.ini:LyricDisplay".as_slice(),
        ),
        (
            "lyric_initial",
            LYRIC_INITIAL,
            b"@theme:/ScreenGameplay:LyricDisplayPosition".as_slice(),
        ),
    ] {
        let value = vm.try_intern(key.as_bytes())?;
        if vm.raw_table_get(helpers, value)? == Value::Nil {
            let code = compile_named(source, name)?;
            let function = vm.execute(&code)?[0];
            super::super::put(vm, helpers, key, function)?;
        }
    }
    Ok(())
}

fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Build>().unwrap();
    let store = data.store.clone();
    let name = data.name.clone();
    let id = {
        let mut guard = store.lock().unwrap();
        if guard.next >= (1u64 << 53) - 1 {
            return Err(call.error(b"actor scene identity exhausted"));
        }
        guard.next += 1;
        let id = guard.next;
        guard.scenes.insert(
            id,
            Scene {
                actors: Vec::new(),
                root: None,
                ended: false,
                sounds_retired: false,
            },
        );
        id
    };
    let previous = {
        let mut guard = store.lock().unwrap();
        let capture = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed);
        std::mem::replace(&mut guard.constructing_capture, capture)
    };
    let result = create(call, &store, id, &name);
    store.lock().unwrap().constructing_capture = previous;
    match result {
        Ok(actor) => store.lock().unwrap().scenes.get_mut(&id).unwrap().root = Some(actor),
        Err(error) => {
            release(call, &store, id)?;
            return Err(error);
        }
    }
    call.push(Value::Number(id as f64))
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    if ["In", "Out", "Cancel"]
        .iter()
        .any(|known| name.eq_ignore_ascii_case(known))
    {
        return transitions::create(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("Timer") {
        let actor = dummy(call, store, scene, "Timer", name, None)?;
        let function = call.new_host_function(timer_seconds, &[])?;
        let bound = get(call, actor, b"__songlua_bound_methods")?;
        set(call, table(call, bound)?, "GetSeconds", function)?;
        return Ok(actor);
    }
    if let Some(index) = crate::top_screen_score_index(name) {
        return score(call, store, scene, index);
    }
    if crate::top_screen_steps_display_index(name).is_some() {
        return steps_displays::create(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("LyricDisplay") {
        return lyrics(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("SongBackground") {
        return background(call, store, scene);
    }
    if name.eq_ignore_ascii_case("Debug") {
        let actor = text(call, store, scene, name, "")?;
        let globals = table(call, helper(call, 5)?)?;
        let center = field(call, globals, "SCREEN_CENTER_X")?;
        let center = number(call, center)?;
        let bottom = field(call, globals, "SCREEN_BOTTOM")?;
        let bottom = number(call, bottom)?;
        for (method, value) in [("x", center), ("y", bottom - 116.), ("zoom", 0.75)] {
            invoke(call, actor, method, &[Value::Number(value as f64)])?;
        }
        return Ok(actor);
    }
    if ["Overlay", "Header", "Footer", "SongForeground"]
        .iter()
        .any(|part| name.eq_ignore_ascii_case(part))
    {
        return dummy(call, store, scene, "ActorFrame", name, None);
    }
    if ["StepsDescription", "PlayerOptions", "ActiveAttackList"]
        .iter()
        .any(|prefix| name.starts_with(prefix))
        || name == "SongOptions"
    {
        let actor = text(call, store, scene, name, "")?;
        invoke(call, actor, "visible", &[Value::Boolean(false)])?;
        return Ok(actor);
    }
    if name.starts_with("OniGameOver") {
        let actor = dummy(call, store, scene, "Sprite", name, None)?;
        blank_texture(call, store, actor)?;
        return Ok(actor);
    }
    Err(call.error(b"screen part is not implemented"))
}

fn timer_seconds(call: &mut HostCall<'_>) -> Result<(), Error> {
    call.push(Value::Number(0.))
}

pub(super) fn text(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
    value: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "BitmapText", name, None)?;
    let value = call.try_intern(value.as_bytes())?;
    set(call, actor, "Text", value)?;
    Ok(actor)
}

pub(super) fn blank_texture(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let path =
        crate::blank_texture::load_native_blank_texture().map_err(|e| call.error(e.as_bytes()))?;
    let path = call.try_intern(path.as_bytes())?;
    sprites::set_texture(call, store, actor, path, false)
}

pub(super) fn append(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    child: TableId,
) -> Result<(), Error> {
    native_children::adopt(call, store, child, parent)?;
    call.raw_table_set(
        parent,
        Value::Number((call.raw_table_len(parent)? + 1) as f64),
        Value::Table(child),
    )?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&parent)
        .unwrap()
        .children
        .push(child);
    Ok(())
}

pub(super) fn named(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    name: &str,
    child: TableId,
) -> Result<(), Error> {
    native_children::adopt(call, store, child, parent)?;
    native_children::insert(call, parent, name, Value::Table(child))
}

fn score(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    index: usize,
) -> Result<TableId, Error> {
    let actor = dummy(
        call,
        store,
        scene,
        "ActorFrame",
        crate::top_screen_score_name(index),
        None,
    )?;
    let frame = dummy(call, store, scene, "Sprite", "", None)?;
    blank_texture(call, store, frame)?;
    named(call, store, actor, "", frame)?;
    let percent = dummy(
        call,
        store,
        scene,
        "PercentageDisplay",
        "ScoreDisplayPercentage Percent",
        None,
    )?;
    let name = crate::top_screen_score_percent_name(index);
    let text = text(call, store, scene, name, "0.00%")?;
    named(call, store, percent, name, text)?;
    named(
        call,
        store,
        actor,
        "ScoreDisplayPercentage Percent",
        percent,
    )?;
    Ok(actor)
}

pub(super) fn invoke(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &str,
    args: &[Value],
) -> Result<(), Error> {
    let function = field(call, actor, name)?;
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"actor function expected"));
    }
    let mut values = Vec::with_capacity(args.len() + 1);
    values.push(Value::Table(actor));
    values.extend_from_slice(args);
    call.call(function, &values)?;
    Ok(())
}

fn number(call: &mut HostCall<'_>, value: Value) -> Result<f32, Error> {
    sprites::number(call, value).map(|v| v as f32)
}

fn lyrics(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "ActorFrame", name, None)?;
    let factory = native_children::helper_function(call, b"lyric_commands")?;
    let commands = call.call(factory, &[])?[0];
    call.with_roots(&[commands], |call| {
        let commands = table(call, commands)?;
        for (name, side) in [("LyricBack", "Back"), ("LyricFront", "Front")] {
            let child = text(call, store, scene, name, "")?;
            let font = call.try_intern(b"Common Normal")?;
            set(call, child, "Font", font)?;
            let changed = get(call, commands, side.as_bytes())?;
            set(call, child, "ChangedCommand", changed)?;
            append(call, store, actor, child)?;
            named(call, store, actor, name, child)?;
        }
        for name in [
            "SetNoReverseCommand",
            "SetReverseCommand",
            "SetOneReverseCommand",
        ] {
            let function = get(call, commands, name.as_bytes())?;
            set(call, actor, name, function)?;
        }
        let initial = native_children::helper_function(call, b"lyric_initial")?;
        let initial = call.call(initial, &[])?[0];
        let initial = assets::text(call, initial)?;
        let function = get(call, commands, format!("{initial}Command").as_bytes())?;
        call.call(function, &[Value::Table(actor)])?;
        Ok(actor)
    })
}

fn background(call: &mut HostCall<'_>, store: &Shared, scene: u64) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "ActorFrame", "SongBackground", None)?;
    let implementation = dummy(call, store, scene, "ActorFrame", "", None)?;
    append(call, store, actor, implementation)?;
    let globals = table(call, helper(call, 5)?)?;
    let width = field(call, globals, "SCREEN_WIDTH")?;
    let width = number(call, width)?;
    let height = field(call, globals, "SCREEN_HEIGHT")?;
    let height = number(call, height)?;
    for (left, top, right, bottom) in [
        (0., 0., 0., height),
        (0., 0., width, 0.),
        (width, 0., width, height),
        (0., height, width, height),
    ] {
        let quad = dummy(call, store, scene, "Quad", "", Some(implementation))?;
        invoke(
            call,
            quad,
            "stretchto",
            &[left, top, right, bottom].map(|n| Value::Number(n as f64)),
        )?;
        invoke(call, quad, "diffuse", &[0., 0., 0., 1.].map(Value::Number))?;
        append(call, store, implementation, quad)?;
    }
    let brightness = dummy(call, store, scene, "ActorFrame", "", Some(implementation))?;
    append(call, store, implementation, brightness)?;
    let side = width / 2. - 20.;
    let prefs = get(call, globals, b"PREFSMAN")?;
    let level = call.with_roots(&[prefs], |call| {
        let function = field(call, table(call, prefs)?, "GetPreference")?;
        call.with_roots(&[function], |call| {
            if !matches!(function, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"preference function expected"));
            }
            let key = call.try_intern(b"BGBrightness")?;
            let value = call
                .call(function, &[prefs, key])?
                .first()
                .copied()
                .unwrap_or(Value::Nil);
            number(call, value)
        })
    })?;
    for (left, right) in [(0., side), (width - side, width), (side, width - side)] {
        let quad = dummy(
            call,
            store,
            scene,
            "Quad",
            "BrightnessOverlay",
            Some(brightness),
        )?;
        invoke(
            call,
            quad,
            "stretchto",
            &[left, 0., right, height].map(|n| Value::Number(n as f64)),
        )?;
        invoke(
            call,
            quad,
            "diffuse",
            &[0., 0., 0., (1. - level) as f64].map(Value::Number),
        )?;
        append(call, store, brightness, quad)?;
    }
    // BackgroundImpl enables owned lookups recursively on its frame nodes.
    for frame in [actor, implementation, brightness] {
        set(
            call,
            frame,
            "__songlua_owned_child_lookup",
            Value::Boolean(true),
        )?;
    }
    Ok(actor)
}

//! ScreenGameplay controls, installed on the screen after its children exist.
use super::super::managers::screen::{Requests, capture};
use super::*;
use deadlib_lua::NativeStack;
use generated_players::dummy;
use sprites::set;

#[derive(Clone)]
struct Binding {
    store: Shared,
    requests: Arc<Mutex<Requests>>,
    enabled: [bool; crate::LUA_PLAYERS],
    method: &'static str,
}

impl Actors {
    // Screen allocation precedes generated player/theme adoption and controls.
    pub(in crate::rust_engine) fn top_screen_base(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
    ) -> Result<ActorScene, Error> {
        let function = vm.new_host_function_with_data(
            create_base,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            (self.store.clone(), context.clone()),
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.registry,
            id: id as u64,
        })
    }

    pub(in crate::rust_engine) fn bind_top_screen(
        &self,
        vm: &mut Vm,
        catalog: Value,
        screen_and_children: [Value; 5],
        enabled: [bool; crate::LUA_PLAYERS],
        requests: Arc<Mutex<Requests>>,
    ) -> Result<(), Error> {
        let mut captures = vec![
            Value::Table(self.registry),
            Value::Table(self.helpers),
            catalog,
        ];
        captures.extend(screen_and_children);
        let function = vm.new_host_function_with_data(
            install,
            &captures,
            Binding {
                store: self.store.clone(),
                requests,
                enabled,
                method: "",
            },
        )?;
        vm.call(function, &[]).map(|_| ())
    }
}

fn create_base(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (store, context) = call
        .function_data::<(Shared, crate::SongLuaCompileContext)>()
        .unwrap()
        .clone();
    let scene = new_scene(call, &store)?;
    let previous = {
        let mut guard = store.lock().unwrap();
        let capture = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed);
        std::mem::replace(&mut guard.constructing_capture, capture)
    };
    let result = (|| {
        let actor = create(call, &store, scene, &context)?;
        store.lock().unwrap().scenes.get_mut(&scene).unwrap().root = Some(actor);
        Ok(())
    })();
    store.lock().unwrap().constructing_capture = previous;
    if let Err(error) = result {
        release(call, &store, scene)?;
        return Err(error);
    }
    call.push(Value::Number(scene as f64))
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    context: &crate::SongLuaCompileContext,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "TopScreen", "ScreenGameplay", None)?;
    for (key, value) in [
        ("__songlua_player1_enabled", context.players[0].enabled),
        ("__songlua_player2_enabled", context.players[1].enabled),
    ] {
        set(call, actor, key, Value::Boolean(value))?;
    }
    let title = call.try_intern(context.main_title.as_bytes())?;
    set(call, actor, "__songlua_main_title", title)?;
    let bpm = crate::display_bpms_text(context.song_display_bpms, crate::song_music_rate(context));
    let bpm = call.try_intern(bpm.as_bytes())?;
    set(call, actor, "__songlua_bpm_text", bpm)?;
    Ok(actor)
}

// Bound methods retain the original screen, enabled players and backing slots.
// Replacing the published screen or GAMESTATE does not retarget saved methods.
fn install(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let catalog = table(call, call.captures()[2])?;
    let slots = get(call, catalog, b"game_state_slots")?;
    let screen = table(call, call.captures()[3])?;
    let mut captures = call.captures().to_vec();
    captures[2] = slots;
    let wheel = call.try_new_table()?;
    call.with_roots(&[Value::Table(wheel)], |call| {
        captures.push(Value::Table(wheel));
        captures.push(helper(call, 5)?);
        for method in [
            "IsLocked",
            "GetSelectedSection",
            "GetSelectedSong",
            "GetSelectedType",
            "GetSortOrder",
            "ChangeSort",
            "SetOpenSection",
            "Move",
        ] {
            let method_captures = method_captures(call, &captures, method)?;
            let function = call.new_host_function_with_data(
                callback,
                &method_captures,
                Binding {
                    method,
                    ..data.clone()
                },
            )?;
            set(call, wheel, method, function)?;
        }
        for method in [
            "GetScreenType",
            "SetMinSecondsToMusic",
            "GetChild",
            "GetLifeMeter",
            "StartTransitioningScreen",
            "SetNextScreenName",
            "SetPrevScreenName",
            "GetNextScreenName",
            "GetPrevScreenName",
            "GetGoToOptions",
            "GetEditState",
            "GetCurrentRowIndex",
            "GetNumRows",
            "GetOptionRow",
            "SetOptionRowIndex",
            "RedrawOptions",
            "IsPaused",
            "PauseGame",
            "AllAreOnLastRow",
            "GetMusicWheel",
            "GetNextCourseSong",
            "PostScreenMessage",
            "SetProfileIndex",
            "Cancel",
            "Continue",
            "Finish",
            "Load",
            "begin_backing_out",
        ] {
            let method_captures = method_captures(call, &captures, method)?;
            let function = call.new_host_function_with_data(
                callback,
                &method_captures,
                Binding {
                    method,
                    ..data.clone()
                },
            )?;
            let bound = get(call, screen, b"__songlua_bound_methods")?;
            set(call, table(call, bound)?, method, function)?;
        }
        Ok(())
    })
}

fn argument(call: &HostCall<'_>, index: usize) -> Value {
    let offset = usize::from(matches!(call.arguments().first(), Some(Value::Table(_))));
    arg(call, index + offset)
}
fn string(call: &HostCall<'_>, value: Value) -> Option<String> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?)
        .ok()
        .map(str::to_owned)
}
fn integer(call: &HostCall<'_>, value: Value) -> Option<i32> {
    match value {
        Value::Number(value) if value.is_finite() => {
            Some(value.round().clamp(i32::MIN as f64, i32::MAX as f64) as i32)
        }
        Value::String(_) => {
            let value = string(call, value)?;
            value
                .trim()
                .parse()
                .ok()
                .or_else(|| value.trim().parse::<f32>().ok().map(|n| n.round() as i32))
        }
        _ => None,
    }
}

fn callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let screen_value = call.captures()[3];
    let first = argument(call, 0);
    match data.method {
        "SetMinSecondsToMusic" => {
            let receiver = table(call, arg(call, 0))?;
            let seconds = call.number(1)? as f32;
            if !seconds.is_finite() || !(0.0..=60.0).contains(&seconds) {
                return Err(call.error(b"music lead-in must be between 0 and 60 seconds"));
            }
            let key = call.try_intern(b"__songlua_min_seconds_to_music")?;
            call.raw_table_set(receiver, key, Value::Number(seconds as f64))?;
            return call.push(Value::Table(receiver));
        }
        "GetOptionRow" => {
            let name = if matches!(first, Value::String(_)) {
                string(call, first).unwrap_or_default()
            } else {
                integer(call, first)
                    .and_then(crate::top_screen_option_row_name_at)
                    .unwrap_or(crate::SONG_LUA_TOP_SCREEN_OPTION_ROWS[0])
                    .to_owned()
            };
            let scene = new_scene(call, &data.store)?;
            data.store.lock().unwrap().constructor_scenes.insert(scene);
            let previous = {
                let mut guard = data.store.lock().unwrap();
                let capture = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed);
                std::mem::replace(&mut guard.constructing_capture, capture)
            };
            let row = option_row(call, &data.store, scene, &name);
            data.store.lock().unwrap().constructing_capture = previous;
            let row = match row {
                Ok(row) => row,
                Err(error) => {
                    release(call, &data.store, scene)?;
                    return Err(error);
                }
            };
            data.store
                .lock()
                .unwrap()
                .scenes
                .get_mut(&scene)
                .unwrap()
                .root = Some(row);
            return call.push(Value::Table(row));
        }
        "GetChild" => {
            let screen = table(call, screen_value)?;
            let Some(name) = string(call, first) else {
                return call.push(Value::Nil);
            };
            let player = crate::top_screen_player_index(&name)
                .map(|i| (i, 4 + i))
                .or_else(|| crate::top_screen_life_meter_index(&name).map(|i| (i, 6 + i)));
            if let Some((index, slot)) = player {
                return call.push(if data.enabled[index] {
                    call.captures()[slot]
                } else {
                    Value::Nil
                });
            }
            let named = registry(call, screen)?;
            return call.with_roots(&[named], |call| {
                let key = call.try_intern(name.as_bytes())?;
                let value = call.table_get(named, key)?;
                if !matches!(value, Value::Nil | Value::Table(_)) {
                    return Err(call.error(b"screen child table expected"));
                }
                call.push(value)
            });
        }
        "GetLifeMeter" => {
            let index = match first {
                Value::Number(n) if n >= 0. && n < crate::LUA_PLAYERS as f64 && n.fract() == 0. => {
                    Some(n as usize)
                }
                Value::String(id) => call.string_bytes(id).and_then(|s| {
                    if s.eq_ignore_ascii_case(b"P1") || s.eq_ignore_ascii_case(b"PlayerNumber_P1") {
                        Some(0)
                    } else if s.eq_ignore_ascii_case(b"P2")
                        || s.eq_ignore_ascii_case(b"PlayerNumber_P2")
                    {
                        Some(1)
                    } else {
                        None
                    }
                }),
                _ => None,
            };
            return call.push(
                index
                    .filter(|&i| data.enabled[i])
                    .map_or(Value::Nil, |i| call.captures()[6 + i]),
            );
        }
        "StartTransitioningScreen" => {
            let screen = table(call, screen_value)?;
            let globals = call.captures()[9];
            let live = data
                .store
                .lock()
                .unwrap()
                .clock
                .live
                .load(std::sync::atomic::Ordering::Relaxed);
            let message = string(call, first);
            {
                let mut stack = call.native_stack()?;
                stack.push(globals)?;
                let globals_index = stack.top();
                side_effect(&mut stack, globals_index)?;
                if live {
                    let message = message
                        .as_ref()
                        .ok_or_else(|| stack.error(b"expected a screen transition message"))?;
                    capture(
                        &mut stack,
                        &data.requests,
                        globals_index,
                        crate::SongLuaLiveRequest::Transition(message.clone()),
                    )?;
                }
            }
            if live {
                for child in children(call, &data.store, screen)? {
                    play(call, &data.store, child, b"Off", None, true)?;
                }
                let named = registry(call, screen)?;
                let out =
                    call.with_roots(&[named], |call| get(call, table(call, named)?, b"Out"))?;
                if out != Value::Nil {
                    transitions::start(call, &data.store, table(call, out)?)?;
                }
                data.requests.lock().unwrap().transition = message;
            }
            return call.push(screen_value);
        }
        _ => (),
    }
    let second = argument(call, 1);
    let arg_count = call.arguments().len()
        - usize::from(matches!(call.arguments().first(), Some(Value::Table(_))));
    let first_text = string(call, first);
    let row = integer(call, if arg_count > 1 { second } else { first });
    let slots = call.captures()[2];
    let wheel = call.captures()[8];
    let globals = call.captures()[9];
    let mut stack = call.native_stack()?;
    stack.push(screen_value)?;
    let owner = stack.top();
    let mut result = screen_value;
    let mut effect = false;
    match data.method {
        "GetScreenType" => stack.push_bytes(b"ScreenType_Gameplay")?,
        "GetGoToOptions" | "AllAreOnLastRow" | "IsLocked" => stack.push(Value::Boolean(false))?,
        "GetEditState" => stack.push_bytes(b"EditState_Playing")?,
        "GetSelectedType" => stack.push_bytes(b"WheelItemDataType_Song")?,
        "GetSelectedSection" => stack.push_bytes(b"")?,
        "GetSelectedSong" => stack.push(Value::Nil)?,
        "GetMusicWheel" => stack.push(wheel)?,
        "GetNumRows" => stack.push(Value::Number(
            crate::SONG_LUA_TOP_SCREEN_OPTION_ROWS.len() as f64
        ))?,
        "GetNextScreenName" | "GetPrevScreenName" | "GetCurrentRowIndex" | "IsPaused" => {
            let key = match data.method {
                "GetNextScreenName" => b"__songlua_next_screen_name".as_slice(),
                "GetPrevScreenName" => b"__songlua_prev_screen_name",
                "GetCurrentRowIndex" => b"__songlua_current_row_index",
                _ => b"__songlua_paused",
            };
            stack.get_field(owner as isize, key)?;
            if data.method == "IsPaused" {
                stack.push(Value::Boolean(stack.to_boolean(-1)))?;
            } else if data.method == "GetCurrentRowIndex" {
                let n = if stack.value(-1) == Some(Value::Nil) {
                    0
                } else {
                    checked_i64(&stack, -1)?
                };
                stack.push(Value::Number(n as f64))?;
            } else if stack.value(-1) == Some(Value::Nil) {
                stack.push_bytes(b"")?;
            } else {
                let text = string_bytes(&mut stack, -1)?;
                stack.push_bytes(&text)?;
            }
        }
        "SetNextScreenName" | "SetPrevScreenName" | "PauseGame" | "SetOptionRowIndex" => {
            let key = match data.method {
                "SetNextScreenName" => b"__songlua_next_screen_name".as_slice(),
                "SetPrevScreenName" => b"__songlua_prev_screen_name",
                "PauseGame" => b"__songlua_paused",
                _ => b"__songlua_current_row_index",
            };
            if data.method != "SetOptionRowIndex" || row.is_some() {
                stack.push_bytes(key)?;
                match data.method {
                    "PauseGame" => stack.push(Value::Boolean(!matches!(
                        first,
                        Value::Nil | Value::Boolean(false)
                    )))?,
                    "SetOptionRowIndex" => stack.push(Value::Number(row.unwrap().max(0) as f64))?,
                    _ => stack.push_bytes(first_text.as_deref().unwrap_or_default().as_bytes())?,
                }
                stack.set_table(owner as isize, false)?;
            }
            effect = true;
        }
        "GetSortOrder" | "GetNextCourseSong" | "ChangeSort" => {
            stack.push(slots)?;
            let slot = stack.top();
            if data.method == "ChangeSort" {
                if let Some(name) = first_text {
                    stack.push(Value::Number(1.))?;
                    stack.push_bytes(name.as_bytes())?;
                    stack.set_table(slot as isize, true)?;
                }
                effect = true;
                result = wheel;
            } else {
                stack.push(Value::Number(1.))?;
                stack.get_table(slot as isize, true)?;
                if data.method == "GetSortOrder" {
                    if stack.value(-1) == Some(Value::Nil) {
                        stack.push_bytes(b"SortOrder_Group")?;
                    } else {
                        let bytes = string_bytes(&mut stack, -1)?;
                        stack.push_bytes(&bytes)?;
                    }
                } else if !matches!(stack.value(-1), Some(Value::Nil | Value::Table(_))) {
                    return Err(stack.error(b"song table expected"));
                }
            }
        }
        "SetOpenSection" | "Move" => {
            effect = true;
            result = wheel;
        }
        "RedrawOptions" | "PostScreenMessage" | "SetProfileIndex" | "Cancel" | "Continue"
        | "Finish" | "Load" | "begin_backing_out" => effect = true,
        _ => unreachable!(),
    }
    if effect {
        stack.push(globals)?;
        let index = stack.top();
        side_effect(&mut stack, index)?;
        stack.push(result)?;
    }
    stack.finish(1)
}

fn string_bytes(stack: &mut NativeStack<'_, '_>, index: isize) -> Result<Vec<u8>, Error> {
    let value = match stack.to_bytes(index)? {
        Some(bytes) => bytes.to_vec(),
        None => return Err(stack.error(b"string expected")),
    };
    if std::str::from_utf8(&value).is_err() {
        return Err(stack.error(b"UTF-8 string expected"));
    }
    Ok(value)
}

fn checked_i64(stack: &NativeStack<'_, '_>, index: isize) -> Result<i64, Error> {
    let value = stack.number(index)?;
    if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
        return Err(stack.error(b"integer out of range"));
    }
    Ok(value as i64)
}
fn side_effect(stack: &mut NativeStack<'_, '_>, globals: usize) -> Result<(), Error> {
    stack.get_field(
        globals as isize,
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
    )?;
    let count = if stack.value(-1) == Some(Value::Nil) {
        0
    } else {
        checked_i64(stack, -1)?
    };
    stack.push_bytes(crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes())?;
    stack.push(Value::Number(count.saturating_add(1) as f64))?;
    stack.set_table(globals as isize, false)
}

fn option_row(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let row = dummy(call, store, scene, "OptionRow", name, None)?;
    let name_value = call.try_intern(name.as_bytes())?;
    let get_name = call.new_host_function(|call| call.push(call.captures()[0]), &[name_value])?;
    let bound = get(call, row, b"__songlua_bound_methods")?;
    set(call, table(call, bound)?, "GetName", get_name)?;
    bind_queries(call, row)?;
    let focus = call.new_host_function(|call| call.push(Value::Number(1.)), &[])?;
    set(call, table(call, bound)?, "GetChoiceInRowWithFocus", focus)?;
    let frame = dummy(call, store, scene, "OptionRowFrame", "", Some(row))?;
    bind_queries(call, frame)?;
    native_children::insert(call, row, "", Value::Table(frame))?;
    let title = screen_parts::text(call, store, scene, "Title", name)?;
    screen_parts::named(call, store, frame, "Title", title)?;
    let members = call.try_new_table()?;
    let group = call.with_roots(&[Value::Table(members)], |call| {
        Ok(call.call(helper(call, 3)?, &[Value::Table(members)])?[0])
    })?;
    call.with_roots(&[group], |call| {
        let text = crate::option_row_default_text(name);
        for index in 1..=crate::LUA_PLAYERS {
            let item = screen_parts::text(call, store, scene, "Item", &text)?;
            native_children::adopt(call, store, item, frame)?;
            call.raw_table_set(
                table(call, group)?,
                Value::Number(index as f64),
                Value::Table(item),
            )?;
        }
        native_children::insert(call, frame, "Item", group)
    })?;
    Ok(row)
}

fn registry(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let registry = native_children::helper_function(call, b"native_registry")?;
    Ok(call.call(registry, &[Value::Table(actor)])?[0])
}
pub(super) fn bind_queries(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let methods = native_children::helper_function(call, b"model_methods")?;
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    for name in ["GetChild", "GetChildren", "GetNumChildren"] {
        let method = get(call, table(call, methods)?, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(invoke_bound, &captures, name)?;
        set(call, table(call, bound)?, name, function)?;
    }
    Ok(())
}
fn method_captures(
    call: &mut HostCall<'_>,
    source: &[Value],
    method: &str,
) -> Result<[Value; 10], Error> {
    let mut captures = [Value::Nil; 10];
    let indices: &[usize] = match method {
        "GetScreenType"
        | "GetGoToOptions"
        | "GetEditState"
        | "GetNumRows"
        | "AllAreOnLastRow"
        | "SetMinSecondsToMusic"
        | "IsLocked"
        | "GetSelectedSection"
        | "GetSelectedSong"
        | "GetSelectedType" => &[],
        "GetOptionRow" => &[0, 1],
        "GetChild" => &[0, 1, 3, 4, 5, 6, 7],
        "GetLifeMeter" => &[6, 7],
        "StartTransitioningScreen" => &[0, 1, 3, 9],
        "GetMusicWheel" => &[8],
        "GetSortOrder" | "GetNextCourseSong" => &[],
        "ChangeSort" | "SetOpenSection" | "Move" => &[8, 9],
        "GetNextScreenName" | "GetPrevScreenName" | "GetCurrentRowIndex" | "IsPaused" => &[3],
        _ => &[3, 9],
    };
    for &i in indices {
        captures[i] = source[i];
    }
    if matches!(method, "GetSortOrder" | "ChangeSort" | "GetNextCourseSong") {
        captures[2] = get(
            call,
            table(call, source[2])?,
            if method == "GetNextCourseSong" {
                b"song"
            } else {
                b"sort"
            },
        )?;
    }
    Ok(captures)
}

//! Selection-aware screen construction in the retained process VM.
use super::*;
use actors::gameplay_theme::Phase;

impl RustSongRuntime {
    /// Project retained chart identities and immutable metadata into the next
    /// scene's context. Public chart getters do not redefine those identities.
    pub fn selected_gameplay_context(
        &mut self,
        context: &SongLuaCompileContext,
    ) -> Result<SongLuaCompileContext, Error> {
        let Value::Table(catalog) = self.vm.rooted(self.catalog)? else {
            unreachable!()
        };
        managers::game_state::scene::context(&mut self.vm, catalog, context)
    }

    /// Initial screen construction. Theme loading is a separate phase so the
    /// caller owns the scene even when a later theme callback fails.
    pub fn construct_gameplay_screen(
        &mut self,
        context: &SongLuaCompileContext,
    ) -> Result<(ActorScene, SongLuaCompileContext), Error> {
        self.gameplay_screen(context, false)
    }

    /// Reconstruct screen-owned state without reinstalling process globals or
    /// reseeding the PRNG. The session must run outgoing End callbacks first,
    /// and retains responsibility for releasing its outgoing ActorScenes.
    /// Old actors stop receiving messages before the new constructor runs.
    pub fn reconstruct_gameplay_screen(
        &mut self,
        context: &SongLuaCompileContext,
    ) -> Result<(ActorScene, SongLuaCompileContext), Error> {
        self.restart_options()?;
        self.actors.clear_message_subscriptions();
        self.gameplay_screen(context, true)
    }

    fn gameplay_screen(
        &mut self,
        context: &SongLuaCompileContext,
        replacing: bool,
    ) -> Result<(ActorScene, SongLuaCompileContext), Error> {
        let Value::Table(catalog) = self.vm.rooted(self.catalog)? else {
            unreachable!()
        };
        managers::game_state::scene::initialize(&mut self.vm, catalog, context)?;
        let selected = self.selected_gameplay_context(context)?;
        if !replacing {
            managers::rebuild_sl(&mut self.vm, &selected)?;
        }
        let (scene, players) = self.actors.gameplay_screen(
            &mut self.vm,
            &selected,
            self.statistics.clone(),
            Value::Table(catalog),
            self.screen.state.clone(),
        )?;
        let screen = self.actor_scene_root(scene).unwrap();
        let result = (|| {
            self.bind_screen_input(screen)?;
            self.publish_screen(screen, players)?;
            if replacing {
                self.reset_stage_statistics(&selected)?;
                self.reset()?;
            } else {
                // Initial native late globals create statistics after the base
                // screen, using the context projected from the seeded slots.
                managers::statistics::install(
                    &mut self.vm,
                    Value::Table(catalog),
                    &selected,
                    self.statistics.clone(),
                    self.clock.clone(),
                )?;
            }
            Ok(())
        })();
        if let Err(error) = result {
            self.release_actor_scene(scene)?;
            return Err(error);
        }
        Ok((scene, selected))
    }

    /// Load the existing bundled phases after screen publication. Failure keeps
    /// partial actors in the supplied scene so its owner can inspect and retire
    /// them. This does not run authored song startup or replay future commands.
    pub fn load_gameplay_theme(
        &mut self,
        scene: ActorScene,
        context: &SongLuaCompileContext,
    ) -> Result<bool, Error> {
        if self.actor_scene_root(scene).is_none() {
            return Ok(false);
        }
        self.begin_actor_preparation()?;
        #[cfg(feature = "test-support")]
        let capture_probe = context.capture_overlay_probe;
        #[cfg(not(feature = "test-support"))]
        let capture_probe = {
            let _ = context;
            false
        };
        for phase in [
            Phase::Combo,
            Phase::Underlay,
            Phase::Overlay { capture_probe },
            Phase::Decorations,
            Phase::Transitions,
        ] {
            if !self
                .actors
                .load_gameplay_theme_phase(&mut self.vm, scene, phase)?
            {
                return Ok(false);
            }
        }
        Ok(true)
    }
}
